local _, GQ = ...

-- GENERATED by scripts/build-locale-quests.py. Do not edit by hand.
-- The client's own quest descriptions and objectives (Questie / QuestieDB data).
if GQ.LOCALE ~= "frFR" then
    return
end

local text = GQ.LocaleText
for k, v in pairs({
    ["\"Here you go, the power source is safely removed and the data is preserved. Well, safe journeys and all that."] = "\"Et voilà, la source d'énergie est enlevée et les données sont préservées. Bien, faites attention sur la route et tout ça.",
    ["- I have heard of you, newcomer. Perhaps it is you that will help us, where others have failed. We tauren have carved a home out of this land, but not without a cost."] = "<name>, j'ai entendu parler de vous. Peut-être saurez-vous nous venir en aide là où d'autres ont échoué. Nous, taurens, avons fait de cette terre notre foyer.",
    [". A task I would ask of you. Have you seen the ruins of Ameth'Aran? If not, you will find them on the eastern side of the main road, some ways to the south."] = "<class>. J'aurais quelque chose à vous demander. Connaissez-vous les ruines d'Ameth'Aran ? Si ce n'est pas le cas, vous les trouverez à l'est de la route principale, à quelque distance au sud.",
    [". The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock. Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars."] = "<name>. La Lame ardente a infesté la caverne appelée le Rocher du crâne, à l'est d'Orgrimmar. Ils y accomplissent des rituels abominables, et brûlent leur propre chair avec des Colliers brûlants.",
    ["... your timing is perfect. I just hope I can compliment your haste as well. I was careless while fighting a few of the venomtails nearby, and one of them stung me deeply."] = "<name>... votre minutage est parfait. J'espère que je pourrai en dire autant de votre célérité. J'ai manqué d'attention en combattant des Queues-venin aux alentours, et j'ai été piqué par l'un d'entre eux.",
    ["A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor. He would be very interested in a sample of the wolf hearts Renferrel sent me."] = "Un collègue de Kalimdor, l'apothicaire Helbrim, étudie les effets des toxines de Lordaeron sur les animaux de Kalimdor. Il serait très intéressé par un échantillon de coeurs de loups que Renferrel m'a envoyés.",
    ["A like you must get pretty hungry out here in The Barrens. Me, I'm starving all day long. Tell you what, I'll fix you up a nice stew. Just need a few dig rats."] = "La Société royale des apothicaires, basée dans la grande ville d'Undercity de Lordaeron, m'a envoyée ici pour une mission très particulière, <name>. Peut-être souhaitez-vous m'aider, et ainsi aider la Dame noire, dans nos efforts pour faire progresser les Réprouvés. J'ai récemment étudié un spécimen rare de flore appelé Fleur de serpent. Je crois qu'en grande quantité cette herbe a un bon potentiel.",
    ["A mudsnout composite? Absolutely brilliant! Why didn't I think of that? Let me contribute my colloid of decay to this devilish brew."] = "Un composé à base de fangemufle ? Absolument merveilleux ! Pourquoi n'y ai-je pas pensé ? Laissez-moi appliquer de mon colloïde de virulence à cette diabolique mixture.",
    ["A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside. Take this vial."] = "Un satyre connu sous le nom de Vylelangue a corrompu les cavernes de Maraudon, mettant en péril la croissance de nombre de plantes, à l'intérieur. Prenez cette fiole, <name>.",
    ["A second encampment of satyrs threatens the land of Felwood towards the north, led by the cruel Xavaric. The vile betrayers and tricksters feed upon the corruption of the native creatures of Felwood."] = "Un second campement de satyres menace Gangrebois, au nord. Menés par le cruel Xavaric, ces maudits traîtres se servent de la corruption qui afflige les créatures locales de Gangrebois.",
    ["A tauren skilled in the ways of the hunt knows that his prey is not for mere trophy. The beasts of the plains provide us with a means of survival."] = "Un tauren compétent dans l'art de la chasse sait que ses proies ne sont pas de simples trophées. Les animaux des plaines nous fournissent ce dont nous avons besoin pour survivre.",
    ["A terrible menace has been laid to rest. The cruel Ossirian has been vanquished. The denizens of Kalimdor would be relieved to know of this victory."] = "Une terrible menace est enfin neutralisée. Ossirian le cruel a été vaincu. Les habitants de Kalimdor seront soulagés lorsqu'ils auront connaissance de cette victoire.",
    ["A truly amazing story! You have my thanks, and the heartfelt gratitude of all who were involved, I can assure you. Through your efforts we are delivered from the mistakes of our past."] = "C'est une histoire stupéfiante, <name> ! Je vous remercie sincèrement. Tous ceux qui ont participé à cette affaire vous expriment leur gratitude.",
    ["A while ago, I had an incident with the Shadowforge Dwarves. They brought me to Angor Fortress to study two types of strange stones from Uldaman."] = "Je viens d'avoir un problème avec les nains Ombreforge. Ils m'ont amené à la forteresse d'Angor pour étudier deux sortes de pierres étranges venant d'Uldaman.",
    ["According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague. Those beasts dwell on the islands in Lake Lordamere to the east."] = "D'après le journal de Berard, la mousse de Furtifs et de Rampants du lac pourrait intervenir dans la composition d'une Peste nouvelle. Ces bêtes vivent sur les îles du lac de Lordamere, à l'est.",
    ["According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands."] = "A en croire les documents que vous avez sauvés de la Caravane, la KapitalRisk a conçu plusieurs projets pour nous chasser de nos terres afin de pouvoir les piller et les exploiter en toute liberté. Je suis épouvanté de voir à quelles extrémités ces odieuses créatures sont prêtes à en venir pour accomplir leurs desseins.",
    ["After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache."] = "Après une analyse attentive de la carte, vous comprenez que vous avez découvert les plans du chef de guerre Dos-hirsute pour assiéger le camp Narache.",
    ["After examining this charm, I see now what must be done. Please take it, and do as I ask. You are to explore the deepest areas of the Ban'ethil Barrow Den."] = "J'ai examiné ce charme, <name>, et je vois maintenant ce qu'il faut faire. Prenez-le et suivez mes instructions. Vous devez explorer les zones les plus reculées du Refuge des saisons de Ban'ethil pour trouver mon corps sans âme...",
    ["After much observation, I have discovered Morganth's plans. He searches for the Scythe of Elune...and he may have found it! If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might."] = "Après une longue surveillance, j'ai découvert les plans de Morganth. Il recherche la faux d'Elune… et il se peut même qu'il l'ait déjà trouvée ! S'il se l'est appropriée, alors les Carmines et le royaume de Stormwind tomberont bientôt sous son joug.",
    ["After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw. It depicts a young, long-haired Paladin with hammer upraised."] = "Une fois le baril sorti de la boue et ouvert, on y trouve une figurine argentée empaquetée avec soin dans la paille. Elle représente un jeune paladin aux cheveux longs, qui brandit un marteau.",
    ["Agmond's tracks lead from the west. It is easy to tell from the bloody smears across rock and sand that the dwarf crawled some distance."] = "Les traces d'Agmond partent de l'ouest. Les traînées de sang sur la pierre et sur le sable vous indiquent que le nain a rampé sur une certaine distance.",
    ["Ain't nothin' that irks me more than losin' these here beautiful horses."] = "Y'a rien qui m'hérisse plus que d'perdre ces beaux ch'vaux, là.",
    ["All right then... if you're sure, we'll sneak out of here. Let us leave when you're ready. Remember, after you've escaped, meet Terenthis back in Auberdine."] = "D'accord... si vous le voulez, nous nous échapperons d'ici. Rappelez vous, une fois que vous aurez quitté ce lieu, allez à Auberdine et rencontrez Terenthis. C'est là que je vais me rendre aussi, et j'y serai probablement avant vous.",
    ["All right, force it is. Let's get out of here as soon as you're ready. We'll fight our way down to the road--Grimclaw should still be there."] = "Ça va, <name>. Sortons de là. Nous nous fraierons un passage jusqu'à la route ; Griffe-sinistre devrait encore y être.",
    ["All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas."] = "Mug'Thol et ses ogres Cassecrête ont envahi les ruines d'Alterac. Il va être difficile de lui infliger une sérieuse punition sans d'abord entamer ses troupes.",
    ["Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals."] = "Bien que je ne sache rien de ce seigneur Azrethoc, je suis d'accord avec Maurin.",
    ["Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key."] = "Bien qu'il ne soit jamais fait mention du soldat Thorsen dans ces rapports, une petite clé en cuivre était cachée dans un des registres d'Herod.",
    ["Ambassador Infernus was sent to Angor Fortress by Ragnaros himself to mind the Shadowforge seeking lost artifacts in Uldaman. It has already meant tremendous casualties for our people, but it has obviously grown worse."] = "L'Ambassadeur Infernus a été envoyé à la Forteresse d'Angor par Ragnaros lui-même, pour suivre les recherches des artefacts perdus des Ombreforge à Uldaman. Cela a déjà coûté d'énormes pertes à notre peuple et la situation empire encore.",
    ["An archmage of great power is overseeing the reactivation of the ley energy node. With the progress they have made, our only hope of stopping them is by killing him."] = "Un archimage de grand pouvoir supervise la réactivation du nœud d'énergie Ley. Vu les progrès qu'ils ont faits, notre seule chance de les arrêter est de tuer cet archimage.",
    ["And again, it is your task to perform the ritual of cleansing. Go to the Thunderhorn Water Well, north of the village, and use the Thunderhorn Cleansing Totem in your ritual."] = "Le totem est prêt, <name>. Il vous faut encore pratiquer le Rituel de purification.",
    ["Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body."] = "Anilia pose ses mains sur vos épaules et vous attire vers elle. Haletante, elle indique l'arche au nord, avant de fermer les yeux pour toujours.",
    ["Anyway, you should check back with me relatively soon... that is if you want to know what was in here. As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you."] = "De toute façon, vous aurez à revenir me voir bien assez tôt… si vous voulez savoir ce qui se trouvait là. Dès que j'aurai trouvé de quoi il en retourne et s'il s'agit bien d'un livre, je n'hésiterai pas à partager cette information avec vous. Pendant ce temps-là, à votre place, j'irais voir Rabine qui s'occupe d'un petit campement d'ours.",
    ["Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air. The crew tried so hard to save my beautiful Maiden's Folly."] = "Argh, quelle horrible vie ! Je devrais être mort sous l'eau, et pas assis ici près d'un feu, respirant de l'air frais. L'équipage a tout fait pour sauver mon merveilleux « Folie de la Vierge ».",
    ["Arnak thinks we're going to be married... but after I declined his offer he came back that night and kidnapped me. My brother tried to stop him, but Arnak was too strong."] = "Arnak pense que nous allons nous marier… Mais après mon refus, il est revenu pendant la nuit et m'a kidnappée. Mon frère a essayé de l'arrêter, mais Arnak était trop fort. Il… il a tué mon frère puis m'a ramenée ici.",
    ["Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain. I shall see to it that his magic is eradicated."] = "Arugal se trouve toujours dans le Donjon d'Ombrecroc. Nous ne pouvons pas faire des Pins argentés une forteresse stratégique pour la Dame noire tant qu'Arugal est vivant. Je vais me débrouiller pour que sa magie soit annihilée, <name>.",
    ["As if crashing into the Loch wasn't bad enough, troggs from the nearby island attacked me and stole my tools and special Blastenheimer Blastencapper explosives."] = "Comme si le crash dans le Loch n'avait pas suffi, des troggs de l'île voisine m'ont attaqué et ont volé mes outils et mes capsuleurs soufflants Blastenheimer spéciaux !",
    ["As you have seen, though the land is in pain, the cycle of life is a powerful thing. Now we must do our part help it along. You must plant these seeds at the center of the destruction, to the west, in the Charred Vale."] = "Comme vous avez pu le constater, <class>, le cycle de la vie demeure une instance puissante, même quand la terre souffre. Vous devez aller planter ces graines au coeur de la destruction, à l'ouest, dans le Val calciné. Sur votre chemin, prenez garde aux harpies et aux élémentaires de feu enragés, fléaux vivants qui sévissent sur cette terre scarifiée.",
    ["As you may know, wyverns are often tamed by orcs for use as mounts. But what is less known is that the venom of a wyvern, in some circles, is more valuable than the beast itself."] = "Comme vous le savez, les wyvernes sont souvent domestiquées par les orcs, qui les utilisent comme montures. Ce que l'on sait moins, c'est que, dans certains cercles, le venin de wyverne est plus recherché que la bête elle-même.",
    ["As you might know, I collect lore. Old lore. Powerful lore. Lore that opens doorways, and lore that can awaken Those Who Sleep."] = "Comme il se peut que vous le sachiez, je recueille le savoir. Le savoir ancien. Le savoir puissant. Le savoir qui ouvre les portes et le savoir qui réveille Ceux qui dorment.",
    ["At last, friends of the Alliance! Help... please... The last thing I remember these foul Orcs overpowered our regiment. Most the men were killed."] = "Enfin, des amis de l'Alliance ! Au secours… Je vous en prie… La dernière chose dont je me souviens est que les orcs ont submergé nos forces. La plupart des hommes ont été tués. J'ai reçu un coup terrible à la tête et tout s'est assombri. Je suis à présent prisonnier dans cette caverne.",
    ["At last, help has arrived! You have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place."] = "Enfin de l'aide ! Vous n'avez pas idée du temps que j'ai passé prisonnier ici ! Je n'arrive plus à me rappeler quand j'ai vu le monde extérieur pour la dernière fois.",
    ["Attention! A reward is being offered for the death of the murloc \"Murkdeep\"."] = "Votre attention ! Une récompense est offerte pour la mort du murloc \"Fondeboue\".",
    ["Avast! Who goes there? Argh, I am but useless without me special enchanted eye. Bad enough to have lost me eyes in battle in the first place!"] = "Eh, qui va là ? Argh, je ne vaux rien sans mon œil enchanté spécial. J'aurais pas dû perdre mes yeux à la guerre pour commencer ! Mais par chance, nous avons débarqué à Menethil et un sorcier de passage a enchanté un œil de verre spécial qui me permet de voir à nouveau.",
    ["Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize."] = "Comme vous avez combattu avec valeur à la bataille d'Hillsbrad, j'ai écrit cette recommandation exaltant vos prouesses au combat, pour que le haut commandement les apprécie.",
    ["Because you proved yourself to be such a go-getter in the jungle, let me tell you about a ferocious raptor that even I have failed to kill."] = "Puisque vous avez montré que vous êtes une telle terreur dans la jungle, laissez-moi vous parler d'un terrible raptor que même moi je n'ai pas réussi à vaincre.",
    ["Before you spoke to me, I had heard of your endeavors... that you had an unyielding desire to prove yourself, that you had an exceptional ability as a, and I now know these things to be the truth."] = "Avant que vous ne me parliez, <name>, j'avais eu vent de vos prouesses…que vous aviez un désir inextinguible de faire vos preuves, que vous étiez admirable, et je sais maintenant que ces choses sont vraies, <class>. Ceux qui excellent comme vous valent d'être reconnus.",
    ["Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you."] = "Je n'ai aucun amour pour la mer, ni pour aucune des créatures que j'ai vu sortir de ses profondeurs. C'est une maîtresse puissante, mais aveugle. Insensible et brutale.",
    ["Behold - the Hand of Iruxos. A gruesome sight indeed. You must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do."] = "Regardez, la Main d'Iruxos ! C'est vraiment une vision horrible. Vous devez l'avoir en votre possession pour pouvoir fermer les portails démoniaques du convent de Mannoroc... C'est ce que je vous demande maintenant de faire.",
    ["Bibbly thinks he is the only goblin in Desolace who knows how to make money. Well, the only caravan brave enough to travel these parts relies on me."] = "Bibbly pense être le seul gobelin de Désolace à savoir comment faire de l'argent. Peuh… Moi, je suis responsable de la seule caravane suffisamment courageuse pour voyager dans ces contrées.",
    ["Big dragons come and make fire at old home. Me smart ogre."] = "Inclinez-vous devant le seigneur Mok'Morokk ! Rexxar faire de moi le puissant chef du clan Cognepierre !",
    ["Black dragons kill many ogre. Kill Tharg's wife."] = "Mok'Morokk fait seigneur par Rexxar. Lui faire attention plus pouvoir que ogres.",
    ["Blackrock Outrunners and Renegades are running ambushes between here and Stonewatch Keep. The leader of the Outrunners is an orc named Tharil'zun--we want this orc."] = "Les renégats et les estafettes Blackrock tendent des embuscades entre ici et le donjon de Guet-de-pierre. Le chef des estafettes est un orc du nom de Tharil'zun – nous voulons qu'il meure.",
    ["Blast the nerve of Firallon! He couldn't sail a skiff through Crystal Lake let alone lead an entire fleet against us. The Bloodsail Buccaneers will pay for their carelessness."] = "La carte montre Baie-du-Butin avec un \"X\" rouge dessiné précisément à l'endroit où vous vous trouvez. Le texte gribouillé dit : \"Vous devez préparer un camp à cet endroit et rester tranquilles. Attendez le signal du poste de commandement du sud avant d'attaquer.",
    ["Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat. He is a blind buffoon. Proof stands two feet away from him and he does not see."] = "Bolvar est un imbécile. J'étais en train de collecter la \"preuve\" à laquelle il tenait tant, pour pouvoir lui fourrer au fin fond de la gorge. Ce n'est qu'un bouffon aveugle. La preuve est sous ses propres yeux et il ne la voit pas.",
    ["Bring me a sample of his skin along with other minor components and I shall craft you leggings of great power."] = "Vous souhaitez prouver votre valeur aux yeux de mon espèce, <mortel/mortelle> ?",
    ["Bring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us. Do it and I'll give ya a belt that our augurs use - one with powerful mojo inside it!"] = "Les augures connaissent le mojo des éléments. Ils s'en servent pour guider la tribu vers la gloire.",
    ["Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!"] = "Nous pensons qu'à l'origine, les épaulières ornées que portent les races mortelles étaient une tentative pour imiter les ailes des dragons.",
    ["Bring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don."] = "Me ferez-vous l'honneur de me rapporter les armures de ceux qui sont tombés en défendant ces terres ?",
    ["Burlguard sent you, did he? Yes, I have spare weapons around here, but first I have a task for you... A while ago a Defias villain Dead-tooth Jack tricked me."] = "Burlguard vous a dit de passer ? Oui, j'ai des armes en trop ici, mais avant vous devez faire quelque chose pour moi... Il y a quelque temps un scélérat défias appelé Jack Dent-Morte m'a escroqué.",
    ["But complications have arisen. A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol."] = "La première fois que nous sommes arrivés dans cette jungle, nous n'avions pas l'intention de déclarer la guerre aux tribus locales. Notre mission d'approvisionnement de Stonard est de la plus haute priorité.",
    ["But the power harnessed in these goggles will allow you to locate them easily. A little gnomish ingenuity goes a long way!"] = "Le trésor repose au fond de la mer depuis si longtemps que les gemmes se sont calcifiées en pierres. Mais le pouvoir contenu dans ces lunettes vous permettront de les localiser facilement.",
    ["But to blow the horn, you need a mouthpiece. To get a mouthpiece, kill Maraudine centaur."] = "Vous nous avez aidés contre les Magram, <name>. À présent, aidez-nous à battre le clan des Maraudine !",
    ["But, there may be more centaur than I thought, I ask you, to fight with me against these vile assassins."] = "Mais il se peut qu'il y ait plus de centaures que je ne le croyais.",
    ["By communion with animals and givin' them up to the spirits when needed, they give us divine guidance. In times past, the haruspex's insight and wisdom gave us an edge in the wars against the splintered tribes of the Gurubashi."] = "L'haruspice est un membre très important de notre tribu, vous avez tout intérêt à écouter ses divinations. Par sa communion avec les animaux, et en les sacrifiant aux esprits lorsque c'est nécessaire, il nous fait profiter des conseils des dieux.",
    ["By order o' 'is eminence, Overseer Oilfist, the rogue Thorium Brotherhood agent an' newly hired commander o' the Dark Iron Slag Pit crew o' the Cauldron, Overseer Maltorius, is to be killed an' 'is head brung back as proof o' the deed."] = "Par ordre de Son Éminence, le surveillant Oilfist, l'agent renégat de la Confrérie du thorium et nouveau chef d'équipe des Sombrefer de la Fosse aux scories du Chaudron, le surveillant Maltorius, doit être tué et sa tête rapportée comme preuve.",
    ["By order of High Executor Darthalia, the human known as Baron Vardus is wanted for crimes against the Forsaken. Vardus is known to be a high-ranking member of the organization known as the Syndicate."] = "Par décret de la Grande Exécutrice Darthalia, l'humain connu sous le nom de baron Vardus est recherché pour crime contre les Réprouvés. Nous savons que Vardus est un membre haut placé de l'organisation dite le Syndicat.",
    ["By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice! A grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard."] = "Par ordre de l'Aînée Torntusk, la vile prêtresse Maléficia et ses sbires doivent être mis à mort ! Une forte récompense est offerte à tous ceux qui parviendront à tuer la vile prêtresse Maléficia et la totalité de sa garde d'élite Aman'zasi.",
    ["By order of the Magistrate of Thelsamar: Chok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary."] = "Par décret du Magistrat de Thelsamar : Chok'sul, l'ogre que l'on croit être l'instigateur et le chef des attaques menées sur la ville de Thelsamar, sur le barrage de Formepierre et sur les excavations, est recherché mort, et mort seulement.",
    ["Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it..."] = "Champion, est-ce bien vous ? Un millier d'années se sont écoulées depuis que le fragment m'a été confié, et c'est à mon heure la plus sombre que quelqu'un se présente pour me le réclamer… Mais que serait une tragédie sans cruauté ?",
    ["Curses! That swab Maury put a lock on his foot, and I can't open it! His loot's inside the foot, and that's what he owes me! We need to find the key to open the lock."] = "Malédiction ! Ce malade de Maury a mis un verrou sur son pied-bot, et je ne peux pas l'ouvrir ! Son butin est à l'intérieur, et c'est ce qu'il me doit ! Nous devons trouver la clé pour ouvrir le verrou.",
    ["Daddy told me to give you this key. He said it opens a chest out back behind the house. He also wanted me to thank you. Did you do a favor for him?"] = "Papa m'a dit de vous donner cette clé. Il prétend qu'elle ouvre un coffre, derrière la maison. Il voulait aussi que je vous remercie. Vous l'avez aidé ?",
    ["Dangerous! The following humans of Hillsbrad have been deemed dangerous and are marked for bounty by High Executor Darthalia: Clerk Horrace Whitesteed."] = "Dangereux ! Les humains d'Hillsbrad dont les noms suivent ont été déclarés dangereux et leurs têtes sont mises à prix par la Grande Exécutrice Darthalia : Commis Horrace Whitesteed.",
    ["Death Knight Darkreaver lords over the Great Ossuary in the Scholomance. He threatens to twist the spirit realm to do his own bidding, and he must be stopped!"] = "Le chevalier de la mort Ravassombre règne sur le Grand ossuaire de la Scholomance. Il se prépare à altérer le monde des esprits pour accomplir ses ténébreuses volontés.",
    ["Deep in Maraudon lives an evil creature of chaos--Princess Theradras is an elemental force of earth related to the Old Gods. Ages ago, she and Zaetar, first son of Cenarius, began a relationship."] = "Profondément enfouie dans Maraudon, vit une malfaisante créature du chaos. La princesse Theradras est une force élémentaire de la Terre, liée aux Dieux très anciens.",
    ["Delgren has asked me to deliver messages and supplies to Sentinel Starbreeze in Auberdine, but I am loathe to leave on my own."] = "Delgren m'a demandé d'apporter un message et du ravitaillement à la Sentinelle Starbreeze à Auberdine, mais je déteste partir seul.",
    ["Demetria is chief advisor to the Grand Crusader. She is called the Oracle due to her 'otherworldly' senses. She has successfully assisted the Crusade in several of their victories against the Scourge."] = "Demetria est la Conseillère en chef du Grand Croisé. On l'appelle l'Oracle en raison de ses sens un peu \"irréels\". Elle a aidé efficacement la Croisade à remporter plusieurs victoires contre le Fléau.",
    ["Did I mention the bad news yet? Its name is Maws: 100 feet of death and destruction. I guess I may have forgotten that little tidbit."] = "Je ne vous ai pas encore dit qu'elle était la mauvaise nouvelle ? Elle s'appelle Crocs-de-la-mer : trente mètres de mort et de destruction. J'avais peut-être oublié de mentionner ce point de détail.",
    ["Did Lieutenant Doren want you to report back to him with that patrol information?"] = "Le Lieutenant Doren a-t-il demandé que vous retourniez le voir avec cette information concernant les patrouilles ?",
    ["Do you think you could help me find my way back to my friend, Rockbiter? He was supposed to be watching me... But I do have a tendency to wander off now and then."] = "Pouvez-vous m'aider à retrouver mon chemin jusqu'à mon ami, Croque-roc ? Il était supposé me surveiller… Mais j'ai tendance à folâtrer de-ci de-là. Il y a tant de choses à voir et je me laisse facilement distraire.",
    ["During the last orc invasion we were forced to smelt our iron down to make bullets, swords and armor."] = "Lors de la dernière invasion des orcs, nous avons été obligés de fondre tout notre fer pour fabriquer des balles, des armures et des épées.",
    ["During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes."] = "Durant vos batailles contre le Fléau à Naxxramas, si vous tombez sur des pièces d'armures désacralisées et des débris d'armures, ramenez-les-moi et je vous forgerai une pièce de cette armure de héros.",
    ["Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal."] = "Edana Serrehaine est la reine des harpies Ruissenord, qui vivent dans les ruines, à l'ouest. Cette créature est le mal à l'état brut ; il paraît que son coeur est de cristal froid, vide de toute émotion sauf de haine pure.",
    ["Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world."] = "Les membres du Marteau du crépuscule, se servant des vieux rites des chaotiques Dieux très anciens, se battent pour les ramener en ce monde et pour y répandre la mort et la terreur.",
    ["Even fragmented, they still possess the powers of the demons trapped inside. The orb of Soran'ruk was broken into two pieces, one was further broken to be used by the acolytes of the Twilight's Hammer in Blackfathom Deeps."] = "Quand les démons de la Légion sont tombés, leurs esprits furent emprisonnés dans des orbes et distribués à leurs mages et leurs démonistes. Beaucoup furent apportés en Azeroth par leurs serviteurs.",
    ["Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered. Interrogator Vishas did this to me!"] = "Bien que ma volonté soit intacte, je ne peux plus servir la Dame noire. Je sens que mes jours sur Azeroth vont prendre fin. Ma force de vie vole en éclats. C'est l'œuvre de l'Interrogateur Vishas !",
    ["Everything was going well, but a large gust of wind blew through the camp and scattered the pages everywhere! I was able to gather most of the pages but many are still strewn about the jungle."] = "Maître Nesingwary va être tellement furieux s'il découvre ça ! Il m'a fait confiance pour relire le manuscrit de son roman « Les vertes collines de Strangleronce ».",
    ["Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them."] = "L'Exécuteur Zygand m'a dit que vous exterminiez des membres de la Croisade écarlate. Les Clairières de Tirisfal en sont remplies.",
    ["Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos... The skull of Gul'dan ensured that none were spared here."] = "Gangrebois était autrefois une terre paisible et sereine… jusqu'à l'arrivée de la Légion. Les infernaux, la destruction, le chaos… Le crâne de Gul'dan s'est assuré que personne ne soit épargné, ici. Tous succombèrent à la corruption. Même à présent, en tant qu'esprit, je me sens emprisonné, et j'ai le sentiment de porter toute la souffrance de cette terre.",
    ["Finally! Someone to rescue me! I can't believe you got past the guards. These zealots from Theramore are out of their minds. They sank our ship and imprisoned me, the only survivor."] = "Enfin ! Quelqu'un est venu me sauver ! Il est incroyable que vous ayez passé les gardes. Ces fanatiques de Theramore sont devenus fous. Ils ont coulé notre navire et m'ont emprisonné.",
    ["Following Khazgorm's plans it should be no problem to fashion an explosive charge Ah, there we go. Now, I am going to entrust you with a special task."] = "En suivant les plans de Khazgorm, la fabrication d'une charge explosive ne devrait pas poser de problème. Ah !",
    ["Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor? I fear that the blood elves will meet a similar deformation."] = "Ces imbéciles d'elfes de sang peinent avec la magie démoniaque. N'ont-ils pas vu ce qui est arrivé aux nagas et aux satyres de Kalimdor ? Je crains que les elfes de sang ne rencontrent pareille déformation.",
    ["For all the work that you have done, you deserve to be well rewarded. Return to Delgren and tell him that Athrikus Narassin lies stilled by your hand, and the Cult of the Dark Strand is beaten and scattered."] = "Vous méritez bien une récompense pour tout ce que vous avez accompli. Retournez voir Delgren et dites-lui qu'Athrikus Narassin gît à terre par vos soins et que le Culte de la Rive noire est vaincu et démantelé.",
    ["For now I will exchange your belt and gauntlets."] = "Vous avez fait la preuve de votre fiabilité, <name>.",
    ["For so long, I have been a puppet of the Grand Crusader. What reason was there to fight against what the Scarlet Crusade had become?"] = "Depuis longtemps, je ne suis qu'une marionnette du Grand croisé. Quelle raison y avait-il de lutter contre ce que la Croisade écarlate était devenue ?",
    ["For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line."] = "Maintenant que l'intérieur est terminé, tout ce qui reste à faire est la couche extérieure. Pour ça, je n'utilise que les meilleures peaux de vieux crocis.",
    ["For you to know the way of our illusionists, go to Zul'Gurub and bring back to me selected Paragons of Power. For this, I will give you arm wraps our illusionists use to weave their spells."] = "Dans notre tribu, les mages sont appelés “illusionnistes”. Leurs incantations emploient des mojos puissants, semant la confusion et le trouble parmi les ennemis de la tribu.",
    ["For your shrewdness and valor, I have a marker here that is good for one piece of armor. I want you to take it to Sara Timberlain at the Eastvale Logging Camp."] = "Pour récompenser votre perspicacité et votre bravoure, j'ai ici un Bon pour une pièce d'armure de Stormwind. Allez trouver Sara Timberlain, au Camp de bûcherons du Val d'est.",
    ["From the corpses of the fallen, the armor is stripped and taken back to Naxxramas to be used for unknown purposes."] = "Bien des héros sont tombés pendant la dernière guerre, et nombreux sont ceux qui ont péri depuis face au Fléau.",
    ["Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge."] = "Garrick Padfoot – un brigand qui harcèle les fermiers et les marchands de la région depuis des semaines – a été vu dans une cabane près des vignes qui se trouvent à l'est de l'abbaye, juste après le pont.",
    ["Gazlowe told me once, \"Rezlak. There's one thing you need to know in life, and that's if you want something done well, do it yourself.\" I can't deal with losing all our caravans, so I'm just going to take matters into my own hands."] = "Gazlowe m'a dit une fois \"Rezlak, il y a une chose que tu dois savoir dans la vie : si tu veux qu'une chose soit faite de manière correcte, fais-la toi-même.\" Je ne peux supporter la perte de nos caravanes, alors je vais m'occuper des choses en personne. Le Ravin asséché est quelque part dans la partie est du canyon de Tranchevent.",
    ["General Shandris Feathermoon would like to speak with you personally."] = "<name>, le général Shandris Feathermoon voudrait vous parler en personne.",
    ["Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west. The slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help."] = "Les Pins-tordus ont été vus ravageant le Refuge des saisons de Ban'ethil, à l'ouest. Les druides dormants vont être pris dans le Rêve d'émeraude pour l'éternité, à moins que nous n'intervenions.",
    ["Gnolls, brutish creatures with no decent business in these lands, have been seen along the borders of Elwynn Forest. A large pack of them, many more than we can handle alone, have infested the woods south of the guard tower yonder."] = "Des gnolls, des animaux brutaux qui n'ont rien à faire ici, ont été aperçus à la lisière de la forêt d'Elwynn. C'est un très grand groupe, bien trop nombreux pour que nous nous en occupions seuls.",
    ["Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined."] = "Technologie gnome… Ce terme était autrefois brandi comme un slogan. Les temps ont changé. Ils ont désormais une nouvelle plate-forme, supérieure à tous nos modèles de Déchiqueteurs combinés.",
    ["Gnomeregan has fallen under the control of those dastardly troggs! The situation is grave but perhaps you can help. Deep in the Deadmines is a functional goblin shredder."] = "Gnomeregan est tombé sous les contrôle de ces troggs maudits ! La situation est grave, mais vous pouvez peut-être nous aider, <name>. Au plus profond des mortemines, il y a un Déchiqueteur gobelin en état de fonctionnement.",
    ["Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?"] = "Salutations, <ami/amie>. Avez-vous des insignes de l'Aube ou de la Croisade que vous aimeriez échanger contre des objets d'une grande puissance ?",
    ["Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power? I must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge."] = "Salutations, <ami/amie>. Avez-vous des insignes de l'Aube ou de la Croisade que vous aimeriez échanger contre des objets d'une grande puissance ? Il faut que je vous prévienne : si vous faites un achat alors que votre niveau de réputation auprès de l'Aube est Amical, vous paierez un très gros supplément.",
    ["Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power? I must warn you; purchases made at a friendly reputation with the Dawn come with a hefty surcharge."] = "Salutations, <ami/amie>. Avez-vous des insignes de l'Aube ou de la Croisade que vous aimeriez échanger contre des objets puissants ? Il faut que je vous prévienne : si vous faites un achat alors que votre niveau de réputation auprès de l'Aube est Amical, vous paierez un gros supplément.",
    ["Greetings, young one. You have a gleam in your eye; I can tell you are eager to venture back to the plains for the hunt. May you bring honor to your clan!"] = "Salut, <mon/ma> jeune <ami/amie> ! Votre oeil brille d'une flamme farouche et je vois que vous avez hâte de retourner dans les plaines pour chasser. Puissiez-vous faire l'honneur de votre clan !",
    ["Greetings. I am Conservator Ilthalaine. My purpose in Shadowglen is to ensure that the balance of nature is maintained."] = "Salutations, <name>. Je suis le Conservateur Ilthalaine. Mon rôle à Sombrevallon est de m'assurer que l'équilibre naturel est maintenu.",
    ["Hail! I can tell by your demeanor that you've seen and done much in this world. Yet I'm willing to wager you haven't seen a piece of armor like this."] = "Voilà une heureuse rencontre, <class>, car j'ai quelque chose qui pourrait vous intéresser. J'ai en ma possession un ensemble d'armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d'une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d'une pièce d'armure plus ordinaire… et d'une petite faveur.",
    ["Hail. Perhaps you've seen those spiders that have taken over the western border? The eight-legged menaces are too much for us to handle, and the Commander hasn't enough manpower to spare so far from Darkshire."] = "Je vous salue, <class>. Peut-être avez-vous vu ces araignées qui ont envahi la frontière ouest ? Nous n'avons pas les forces nécessaires à une attaque, et le commandant n'a pas suffisamment d'hommes pour en envoyer si loin de Darkshire.",
    ["He must be stopped! Take this sacred cord, and string through it the heads of the high priests responsible for channeling our gods' energy."] = "C'est vrai. Hakkar réside désormais dans Zul'Gurub, où il baigne dans le pouvoir de nos dieux.",
    ["He told me of its demonic red eyes, razor-sharp talons and venomous bite. As fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder."] = "Mon grand-père m'a conté sa bataille avec la créature nommée Mazzranache. Il m'a parlé de ses yeux rouges, démoniaques, de ses serres aiguisées comme des rasoirs et de sa morsure venimeuse.",
    ["He's done it this time! Bad enough that Gelriz's muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate!"] = "Cette fois, c'en est trop ! Ce n'était pas assez que ce Gelriz vire les nababs invités par les princes marchands, à présent il essaie de s'immiscer dans les affaires du plus célèbre des pirates !",
    ["Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon."] = "Retournez voir Belgrom à Orgrimmar pour lui dire que Moktar fait tout ce qu'il peut aux Mille pointes. Dites-lui aussi que mes études progressent et que je pourrai lui donner des détails assez vite.",
    ["Heathens have a place in the tribe. Heathens are freethinkers of Zandalar."] = "Vous êtes <un incroyant/une incroyante>. Les incroyants ont une place au sein de la tribu.",
    ["Heavens no! Poor Rustlocke. 'Tis quite a tragedy indeed. We must not let his death pass in vain."] = "Une explosion monstrueuse a grondé à travers les collines. C'tait horrible, j'vous l'dis ! De bons soldats sont morts en défendant le viaduc de Thandol. Longbraid dit que nous prendrons notre revanche sur les Sombrefer avant que tout cela ne soit fini.",
    ["Help me make some Westfall Stew! Come back with the following ingredients: 3 Stringy Vulture Meat 3 Goretusk Snouts 3 Murloc Eyes 3 Okra"] = "Aidez-moi à faire du ragoût de la marche de l'Ouest. Ramenez les ingrédients suivants : 3 morceaux de Viande filandreuse de vautour ; 3 Groins de Broche-tripes ; 3 Yeux de murloc ; 3 Okras.",
    ["Here is some encased ooze created from the Felwood samples you recovered. Take the case to Un'Goro Crater and find a pure ooze... the primal variety will do nicely."] = "Voici un peu de Limon créé à partir des échantillons récupérés à Gangrebois. Portez cette caisse au Cratère d'Un'Goro et trouvez du Limon pur... la variété primitive fera parfaitement l'affaire.",
    ["Here you go. Bring this message to Master Carevin. A few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today."] = "Voilà, <name>. Portez ce message à maître Carevin. <Il sort promptement un morceau de parchemin décoloré et vous le tend.> Encore d'autres comme vous, et nous pourrons vaincre les Veilleurs ! Peut-être alors serions-nous en mesure d'achever l'œuvre à laquelle si peu d'entre nous se sont attelés.",
    ["Here's your cask of Evershine. And again, thank you for the hunting earlier."] = "Voici votre tonneau d'Evershine, <name>. Et merci encore pour la partie de chasse.",
    ["Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened."] = "Voilà, prenez ceci et posez-la sur sa tombe. Peut-être… je ne sais comment… comprendra-t-il que je vais bien, et que personne ne le considère responsable de ce qui est arrivé. <Les larmes perlent à ses yeux à présent, tandis qu'elle enlève une bague de sa main droite, et la presse dans votre paume.> Et...",
    ["Hey!! Come here! My raiders and I are about to attack the Silverwing Outpost to the west. Our target is its leader, Duriel Moonfire. Scouts report the outpost is defended heavily with sentinels and warriors."] = "Hé ! <class> ! Venez par ici ! Mes soldats et moi sommes sur le point d'attaquer l'avant-poste d'Aile-argent, plus à l'ouest. Notre cible, cette fois, est leur chef, Duriel Moonfire.",
    ["Hey. Be careful 'round here. There be Dark Iron dwarves all around--looked like the Shadowforge clan. They just attacked the excavation site I was workin' at--killed nearly everyone there, including my boss Hammertoe."] = "Bonjour, <name>. Faites attention par ici. Il y a des nains Sombrefer partout : ils ressemblaient à ceux du clan Ombreforge. Ils viennent juste d'attaquer le site de fouilles où je travaillais...",
    ["Hey. I been sent to the Crossroads to watch over the land and take note of its happenings for my masters in Orgrimmar. One object of my studies are the insect-like creatures found to the south in the Field of Giants."] = "Hé <name> ! On m'a fait venir à la Croisée pour surveiller la zone et noter ce qui s'y déroule, pour mes maîtres à Orgrimmar. L'un de mes sujets d'étude est cette créature, ressemblant à un insecte, et que nous avons découverte au sud dans le Champ des géants.",
    ["Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us."] = "Hezrul Marque-de-sang est le chef des centaures Kolkar dans les Tarides. Il est féroce, brutal et malin. L'éliminer sèmerait la confusion et briserait l'unité des Kolkar.",
    ["High Executor Darthalia sent me to keep watch of Dun Garok from a distance. I had set up camp just out of sight. But when morning came and I had to boil water, I left to gather firewood."] = "La Grande Exécutrice Darthalia m'a envoyé surveiller Dun Garok de loin. J'ai établi mon camp juste au-delà de leur champ de vision. Mais ce matin, pour faire bouillir de l'eau, je suis allé chercher du bois.",
    ["Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\" He drove off the beast, but not before it mauled him savagely."] = "Hildelve écrit dans son journal qu'il a été attaqué par Griffe galeuse, un \"gigantesque ours Griffeglace\".",
    ["How can one truly hope to win against a foe that is not even really there? We Zandalar know the power of this, and as such illusionists hold a honored place within the tribe."] = "La magie est une force brute, primitive, que seuls les plus forts peuvent modeler. Le mojo est une extension de notre pouvoir, et l'un de ses emplois les plus puissants est l'illusion.",
    ["I am devising a potion that requires rare mushrooms, mushrooms that grow only in a certain cave. The cave lies behind Cliffspring Falls, to the east and slightly north along the mountains."] = "Je prépare une potion qui nécessite des champignons rares, des champignons qui ne poussent que dans une certaine caverne. La caverne en question se trouve au-delà des Chutes de la Bondissante, à l'est et légèrement au nord le long des montagnes.",
    ["I am so lost! My wife, Torta, sent me out to fetch dinner and I must have taken a wrong turn somewhere. Would you be so kind as to lead me back to Torta?"] = "Je suis complètement perdu ! Ma femme, Torta, m'a envoyé chercher le dîner et j'ai dû prendre le mauvais chemin quelque part. Auriez-vous l'amabilité de me guider vers Torta ?",
    ["I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission. It may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains."] = "<name>, il est sûr que Tyrande Whisperwind en personne voudrait vous remercier de prendre part à cette mission. Il n'y paraît peut-être pas, mais votre aide pourrait renforcer notre position dans les Serres-Rocheuses.",
    ["I am the new magistrate of Southshore, recently assigned after the assassination of the previous magistrate."] = "Je suis le nouveau Magistrat de Southshore, assigné ici suite à l'assassinat du précédent Magistrat.",
    ["I am the only survivor from our caravan attack by the centaur! A rare yet mighty panther is guarding my best gizmo, which is around his neck."] = "Je suis le seul survivant de l'attaque de notre caravane par les centaures ! Une panthère rare mais puissante garde mon meilleur bidule autour du cou !",
    ["I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me an ordinary belt and a set of gloves that you wish to upgrade."] = "Vous avez fait la preuve de votre fiabilité, <name>. Je suis sûr que vous m'aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.",
    ["I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gauntlets that you wish to upgrade."] = "Vous avez fait la preuve de votre fiabilité, <name>. Je suis sûr que vous m'aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.",
    ["I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gloves that you wish to upgrade."] = "Vous avez fait la preuve de votre fiabilité, <name>. Je suis sûr que vous m'aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.",
    ["I came to Shadowglen to observe the webwood spiders that dwell in the Shadowthread Cave."] = "Je suis venu à Sombrevallon pour observer les araignées Tissebois qui vivent dans la grotte de Sombrefil.",
    ["I can make you a protective item that'll be of assistance in the fight against our enemy. I shall need a Qiraji drape, which I'll resize for you of course."] = "Je suis content de voir que vous allez nous aider pour notre offensive en Ahn'Qiraj, <name>. J'aimerais vous offrir un objet de protection, qui pourra vous servir contre notre ennemi, <class>.",
    ["I can't lift the curse from the Eye of Paleth."] = "Je ne peux pas lever la malédiction de l'Oeil de Paleth.",
    ["I do not know why, but a festering grows within the Wetlands. Fen Creepers have risen. They are diseased, fevered blisters on the land, and for the fever to break they must be dispatched and allowed to settle back into the marshes."] = "Je ne sais pas pourquoi, mais il y a une prolifération maligne dans les Paluns. Les Rampants des tourbières se manifestent. Ils sont malades et répandent leur fièvre partout.",
    ["I entrust you with the Gem of the Serpent. Place this gem on the Serpent Statue's hand on Ranazjar Isle, a small island northwest of here. Placing it will summon the one who protects the Book of the Ancients."] = "<name>, je vous confie la Gemme du serpent. Placez cette gemme dans la main de la Statue du serpent qui se trouve sur l'île de Ranazjar, une petite île au nord-ouest d'ici. En même temps, vous appellerez celui qui protège le Livre des Anciens.",
    ["I fear the ancient statuette's secrets will remain forever hidden unless you find the key to its ancient lock. That key is a ring, the Ring of Zoram."] = "J'ai peur que les secrets de l'ancienne statuette ne restent un mystère tant que vous n'aurez pas trouvé la clé qui ouvre cette vieille serrure. Cette clé est un anneau, l'Anneau de Zoram.",
    ["I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step. But I am no longer the hero..."] = "<name>, je m'en souviens enfin… Je suis venu ici pour combattre Blazerunner. J'ai fait un long voyage, et il s'agissait de la dernière étape. Mais ce n'est plus moi le héros… c'est vous. Avec tout ce que vous avez déjà accompli, c'est à vous d'en finir, pas à moi.",
    ["I find myself in quite a pinch here. The bottles are close to running dry. The latest booze shipment is long overdue. The orc invasion has been hell."] = "Je suis dans une situation désespérée, <name>. Mes réserves sont presque à sec. La dernière cargaison de boisson aurait dû arriver il y a bien longtemps. L'invasion des orcs a été un enfer.",
    ["I guess I'd better think about getting out of here, also. It won't take long for word of what happened here to spread to the higher ups, and I'm sure they wouldn't take too kindly to meeting me again."] = "Vous savez, avant j'étais la seconde personne la plus importante ici sur ce site. Tout a changé quand Gerenzo est arrivé.",
    ["I had a month's worth of dried meats salted and locked away for the cold season. Kept it locked so the bears wouldn't get it! But while I was off hunting deer, that beast, Old Icebeard, made off with the meat locker."] = "J'avais un mois de réserves de viande séchée et salée que j'avais stockées pour la saison froide. C'était hors d'atteinte des ours, dans une caisse fermée ! Mais pendant que j'étais à la chasse au daim, cette bête, le Vieux Barbeglace, est venue et repartie avec ma caisse de viande.",
    ["I hate those nasty timber wolves! But I sure like eating wolf steaks... Bring me tough wolf meat and I will exchange it for something you'll find useful."] = "J'ai horreur de ces maudits loups des bois ! Mais j'aime beaucoup en déguster des steaks… Apportez-moi de la viande de loup coriace et je vous donnerai en contrepartie quelque chose que vous devriez trouver utile. On peut trouver de la viande de loup coriace en chassant les loups des bois et les jeunes loups qui parcourent la campagne de Northshire.",
    ["I have a lead on an even BETTER source of hides, if that's even possible to believe! In the northern parts of Feralas - deep within Rage Scar Hold - are another throng of yetis."] = "J'ai une piste qui pourrait nous conduire à une source de peaux encore MEILLEURES. Incroyable, non ?",
    ["I have cutting to do. I can't tell you what I'm going to cut, but... I need myself a blade. A certain blade... Some people call it a sword. I call it a swing blade."] = "Je dois découper. Je ne peux pas vous dire quel type de découpage je vais faire, mais j'ai besoin d'une lame… Mais pas n'importe quelle lame ! Il y en a qui l'appellent Epée d'acier lunaire. Moi je l'appelle Epée à double tranchant. Allez-vous m'aider ? Peut-être que vous la trouverez en ville, peut-être que vous pourrez la faire faire chez un forgeron.",
    ["I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas."] = "J'ai découvert un moyen d'utiliser les carapaces des démons des cryptes. En combinant ces fragments avec des restes d'armures désacralisées perdues dans Naxxramas, je peux façonner une armure mortelle et extrêmement légère.",
    ["I have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality. I'd be willing to trade the bracers for ordinary ones in exchange for a small favor."] = "Voilà une heureuse rencontre, <class>, car j'ai quelque chose qui pourrait vous intéresser. J'ai en ma possession un ensemble d'armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d'une qualité bien supérieure à la moyenne.",
    ["I have not long to live... so... so... weak....the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel... But before I... d-d-die......my wife, Treshala..."] = "Il ne me reste plus beaucoup de temps... Tellement... Tellement faible... Le brave Lonebrow a été envoyé pour avertir Falfindel... Mais avant que je ne m-m-meure... ...",
    ["I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind."] = "J'ai préparé un rapport pour le roi. Je crois que vous devriez le lui remettre, en même temps qu'une explication de vos découvertes. N'ayez crainte, il vous récompensera sûrement pour vos actions.",
    ["I have received reports that a group of undead are holing up to prepare for an attack against us. Armed with this information, we can turn the tables and attack them first, nipping their little plan in the bud."] = "J'ai reçu des rapports indiquant qu'un groupe de morts-vivants se cache pour préparer une attaque contre nous. Armés de cette information, nous pouvons retourner la situation en les attaquant les premiers et réduire leur plan minable à un simple souvenir cocasse.",
    ["I have rendered the spores you gave me into an emulsion. I must now send it to my associate, Apothecary Zamah. If you were to carry this to her, she can offer you something from our stores of alchemical goods."] = "J'ai fait une émulsion avec les spores que vous m'avez apportées. Je dois à présent l'envoyer à mon associée, l'Apothicaire Zamah. Si vous pouviez la lui apporter, elle pourra vous offrir quelque chose de nos magasins d'alchimie.",
    ["I have reshaped the Mind's Eye into a Soul Gem. Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul."] = "J'ai façonné la Vue de l'Esprit dans une Gemme d'âme. Cette gemme possède deux fonctions : vous devez d'abord l'utiliser pour étourdir Yenniku et, une fois qu'il est inconscient, placer la gemme sur sa tête afin d'emprisonner son âme.",
    ["I have the digest for you. I need not tell you to take great care with it. And to keep it far from unfriendly hands. This book holds many truths......And the truth can burn."] = "J'ai le livre pour vous, <name>. Je n'ai pas besoin de vous prévenir de bien y faire attention. Et de le garder hors de portée de nos ennemis. Ce livre contient de nombreuses vérités...",
    ["I hear Lord Wishock enjoyed his beverage. You have served us well. The Warlocks of Stormwind will be able to practice our ways without disturbance, thanks to you."] = "J'ai entendu dire que le seigneur Wishock avait apprécié ce breuvage. Vous nous avez bien servi, <name>. Les démonistes de Stormwind seront capables de s'exercer sans être dérangés et ceci grâce à vous.",
    ["I hear you were enlisted by Darthalia to wage war on the humans of Hillsbrad. So jealous I am..."] = "J'ai entendu dire que vous étiez <recruté/recrutée> par Darthalia pour mener l'offensive contre les humains d'Hillsbrad. Je vous envie tellement… Tandis que vous vous amuserez – à tuer des humains, à piller, à terroriser les innocents – je resterai coincé ici, à Moulin-de-Tarren, à monter la garde et à me morfondre.",
    ["I hope you're here to lend us a hand. After the last trogg attack, we could use all the help we can get. I hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception."] = "J'espère que vous êtes là pour nous donner un coup de main, <class>. Après la dernière attaque des troggs, nous avons besoin de toute l'aide possible ! Je sais que ces canailles pullulent dans toutes les régions et on dirait que les Frigères ne font pas exception.",
    ["I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff!"] = "Je viens juste d'arriver dans Feralas et j'ai appris que les ogres Gordunni qui y résident gardent d'intéressants minéraux. Impossible de savoir ce qu'ils projettent, mais ils protègent leurs stocks farouchement et les enterrent pour empêcher qu'un fou comme moi ne mette la main dessus.",
    ["I just picked up this shredder from Ratchet and I was on my way back to the Warsong Lumber Camp, where I am supposed to be on duty."] = "Je viens de trouver ce déchiqueteur à Ratchet.",
    ["I look at my undeath as a malady. An illness that merely requires treatment; however, it is also a great blessing for the Argent Dawn. What better vessel to smite the heathens of the Scourge than through the undead?"] = "Je considère ma nature cadavérique comme une maladie, <name>. Un problème de santé qui nécessite des soins. C'est également une bénédiction pour l'Aube d'argent.",
    ["I love crab. Crabs are the fruit of the sea! You can bake it, barbecue it, boil it, and broil it. They're pan fried, deep fried, and stir fried."] = "J'adore le crabe, ce fruit de mer par excellence ! Vous pouvez le faire griller, l'ébouillanter, le braiser, en faire des beignets frits, des acras, le déguster en salade ou le consommer en soupe ; voilà tout ce qu'on peut faire avec. Je suis ici en train de pêcher en ce moment, et je ne peux donc pas me procurer les morceaux de belle chair de crabe dont j'ai besoin. Vous pouvez en trouver sur les clampants des récifs et sur les clampants des marées incrustés.",
    ["I make no pretenses, maggot. The darkness Plagueheart items hold could very well destroy the both of us."] = "Ce n'est pas pour rire, espèce de ver de terre ! Les objets pestecœur renferment des ténèbres susceptibles de nous détruire tous les deux.",
    ["I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones."] = "J'ai rencontré Gerenzo une fois, mais laissez-moi vous dire qu'il n'est pas très beau à voir. On dirait que sa chair est en train de pourrir, et il s'est fait greffer du métal et des accessoires sur le corps.",
    ["I need some underbelly scales from black dragon whelps to pay for the shoes Argus sent me from Goldshire."] = "J'ai besoin d'écailles ventrales de dragonnet noir pour payer les fers qu'Argus m'a envoyés de Goldshire.",
    ["I need you to venture into Hive'Regal and find what became of my dearest Natalia. This will be no easy task for you. Before you dive headlong into the maw of madness, make sure that you go back and speak with those dwarves."] = "Je veux que vous alliez à la Ruche'Regal pour trouver ce qu'il est advenu de ma chère Natalia, <name>. Cette tâche ne sera guère aisée si vous y allez <seul/seule>. Je vous conseille d'emmener des amis.",
    ["I now present you with the Water of the Seers. When you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, it will take a few moments before the vision materializes before the fire."] = "Vous allez maintenant être <confronté/confrontée> à l'Eau des Prophètes. Quand vous vous sentirez <prêt/prête>, consommez-la en face du feu tribal. Une fois bue l'eau sacrée, la vision se matérialisera rapidement devant le feu.",
    ["I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead."] = "J'ai servi autrefois la Croisade écarlate avec honneur, fidélité et fierté. J'ai cru que sa cause était noble : débarrasser Azeroth des morts-vivants.",
    ["I put my faith in you and anyone you can muster to help free me. The great Skymane King Mukla is my captor. He commands the beasts of this island, and they keep me here against my will with the aid of this chain."] = "La note dit, d'une écriture plutôt élégante : A quiconque peut m'aider, Je vous en prie, j'ai désespérément besoin d'aide. Un grand Crin-de-ciel me détient captive sur une île des mers du Sud. Les étoiles, la nuit, me sont étrangères et sont obscurcies par les arbres de la jungle.",
    ["I sent my apprentice out into the marshes to skin some of our famous giant Wetlands crocolisks. When he didn't return, I went out to look for him..."] = "J'ai envoyé mon apprenti dans les marécages pour chasser les fameux crocilisques géants des Paluns. Comme il ne revenait pas, je suis parti à sa recherche et l'ai retrouvé.",
    ["I should have known. My arch-enemy, Doctor Weavil, up to his old tricks! And now, thanks to your failure in Winterspring, Doctor Weavil has destroyed my book!"] = "J'aurais dû m'en douter ! Mon ennemi juré, le docteur Dwenfer, a récidivé ! Et maintenant, à cause de votre échec au Berceau-de-l'Hiver, le docteur Dwenfer a détruit mon livre !",
    ["I speak of Elementium, mortal. Find and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power."] = "À en croire les théories d'Arygos, l'élément qui naît des conflits entre les Dieux très anciens et leurs séides peut devenir redoutable pour eux lorsque toutes les conditions sont réunies. Je parle de l'élémentium, <mortel/mortelle>.",
    ["I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?"] = "Je suppose que j'apprendrai en le faisant… Ça ne devrait pas être trop difficile. Juste quelques boutons par-ci par-là, et un levier ou deux… Alors, êtes-vous <prêt/prête> à y aller ?",
    ["I take pride in my leather work, and I feel it shows; quality should never be compromised. Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!"] = "Je suis fier de mon travail et je sais que cela se voit : la qualité ne doit jamais être dévalorisée. Quiconque dit que la qualité n'est pas primordiale ferait également croire que les abysses sont lumineux.",
    ["I think I can fix the samophlange, but I'm going to need the user's manual first."] = "Je pense pouvoir réparer le Samophlange, mais je vais avoir besoin du manuel d'utilisation tout d'abord.",
    ["I trust the Valley of Trials will teach you much, young. I was sent to the Valley to guide you, but I have discovered a growing taint here..."] = "Je suis sûre que la Vallée des épreuves vous enseignera beaucoup, jeune <class>. J'ai été envoyée dans la Vallée pour vous guider, mais j'y ai découvert une menace croissante.",
    ["I used to sail a ship from here all the way to Ratchet, in Kalimdor. I was a successful captain with a sterling reputation. Until... Those cursed sea giants ruined me!"] = "Dans le passé, je pilotais un navire d'ici jusqu'à Ratchet, en Kalimdor. J'étais un grand capitaine avec une solide réputation. Jusqu'à ce que… Ces maudits géants des mers m'apportent la ruine ! Ils ont détruit mon bateau, tué mon équipage, et m'ont abandonné dans un canot.",
    ["I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade."] = "On m'a envoyée ici avec un petit groupe de Sentinelles pour protéger l'arbre-oracle des harpies qui ont construit leurs nids tout autour de la clairière.",
    ["I was on my way to Maestra's Post to meet Liladris Moonriver, but I decided to stop here and take a short nap. Ever since I awoke from the emerald dream, I have been so sleepy..."] = "J'étais parti en direction du Poste de Maestra pour rencontrer Liladris Moonriver lorsque je décidai de m'arrêter et de me reposer un peu. Depuis que je me suis extirpé du Rêve d'émeraude, j'ai tout le temps sommeil… <bâille> Auriez-vous l'obligeance de me montrer le chemin ?",
    ["I was playing near the Fargodeep Mine, and I think I dropped, er...I mean I saw, the old lady's necklace. Don't ask me how it got there...it wasn't me!"] = "Je jouais près de la mine de Fargodeep, et je pense que j'ai fait tomb... Euuuuh...",
    ["I was sent to Grom'gol to aid Nimboya on his quest, but... I too have reasons for being here. The Bloodscalp tribe is enemy to our tribe. Collecting trophies of our enemies gives us power over them."] = "J'ai été envoyé à Grom'gol pour aider Nimboya dans sa quête, mais j'ai aussi des raisons personnelles d'être là. La tribu des Bloodscalp est l'ennemie de la nôtre. Collecter les trophées de nos ennemis nous donne du pouvoir sur eux. Vous pouvez aider notre tribu en chassant nos ennemis.",
    ["I was sent to the Valley to guide you, but I have discovered a growing taint here... A group that calls itself the Burning Blade has a coven here in the Valley of Trials."] = "Je suis sûre que la Vallée des épreuves vous enseignera beaucoup, jeune <class>. J'ai été envoyée dans la Vallée pour vous guider, mais j'y ai découvert une menace croissante.",
    ["I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb."] = "Je vais de ce pas commencer à confectionner votre orbe et insuffler votre nouveau démon en lui. Quand cela sera fait, vous pourrez choisir de l'avoir sous la forme d'un orbe ou d'un bâton.",
    ["I will give you a weapon, but first you must aid me. The Razormanes to the northwest came into my camp a few nights past."] = "Je vais vous donner une arme, <name>, mais d'abord vous devez me venir en aide. Les Tranchecrins du nord-ouest sont venus dans mon camp il y a plusieurs nuits.",
    ["I will put the robe together for you now. It will take but a few moments. Do not go far."] = "Je vais maintenant confectionner la robe pour vous. Ne vous éloignez pas, je n'en ai pas pour longtemps.",
    ["I'll go make the wands now."] = "Je vais aller fabriquer les Baguettes magiques maintenant.",
    ["I'll leave it to you to get Tazan's satchel open, and return to me with its contents. The locking mechanism is complex, so it would probably be easiest if you obtained the key."] = "Le Chef de guerre utilise des méthodes trop subtiles. Par prudence, il veut éviter de déchaîner le pouvoir de la Horde.",
    ["I'll tell you what. If you give me those unfired gauntlets, I will teach you how to make a set all your own."] = "Par la barbe de Thaurissan ! Où les avez-vous trouvés ?",
    ["I'm a scientist, but also a treasure hunter at heart! Long ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz'rilla, a hydra they worshipped as a deity."] = "<name>, je suis un scientifique mais au fond de moi je suis aussi un chasseur de trésor ! Il y a longtemps, quand les trolls occupaient ces terres, ils ont créé de nombreux ornements à l'image de Gahz'rilla, une hydre qu'ils adorent comme divinité.",
    ["I'm behind on my report, and could use your help. I just managed to find where the trolls are holed up, but I saw so many trolls, I was afraid to go in."] = "Je suis sur mon rapport et j'ai besoin de votre aide, <name>. Je viens juste de trouver où se cachent les trolls, mais ils sont si nombreux que j'ai peur d'y aller.",
    ["I'm glad to hear you're aiding us in our attack on Ahn'Qiraj. I can make you a protective item that'll be of assistance in the fight against our enemy."] = "Je suis content de voir que vous allez nous aider pour notre offensive en Ahn'Qiraj, <name>. J'aimerais vous offrir un objet de protection, qui pourra vous servir contre notre ennemi, <class>.",
    ["I'm going to have to do something about the giants if I stay out here! They're certainly not good for business, now are they?"] = "Il va falloir que je fasse quelque chose pour ces géants si je reste ici ! Ils ne sont vraiment pas bons pour les affaires !",
    ["I'm going to need more samples. But--and I don't know how to put this--they have to be pure samples. I know, I know. \"What does 'pure' mean, Laris?\" I'm not sure."] = "Je vais avoir besoin de plus d'échantillons, <name>. Mais ces échantillons doivent être purs. Je sais, je sais, \"Qu'est-ce que ça veut dire ‘purs', Laris ?\". Je sais que ceux-ci sont corrompus...",
    ["I'm making a flying machine! I got stranded here, and I'm absolutely horrible at finding my way around. I'd take a gryphon or wind rider back to Gadgetzan, but those beasts just scare me to death."] = "Je fabrique une machine volante ! Je suis coincé ici et je n'ai aucun sens de l'orientation. Je pourrais prendre un gryphon ou un cavalier céleste pour rentrer à Gadgetzan, mais j'ai une peur bleue de ces bestioles.",
    ["I'm on a quest, a quest to make the perfect stout. I know I can do it -- brewing's in my blood. I just need to find the right recipe... The Frostmane trolls grow a plant, shimmerweed, high up in the hills to the east."] = "Je cherche à faire la bière parfaite. Je sais que je peux le faire : le brassage, j'ai ça dans le sang. Je dois juste trouver la bonne recette... Les trolls Frostmane cultivent une plante, la chatoyante, en haut des collines à l'est.",
    ["I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her."] = "J'ai déjà vu Kinelory dans un état pire après toute une nuit passée dans une taverne. Vous avez bien fait de la protéger.",
    ["I, the great Bartolo, shall make for you the world famous, Alliance renowned, Yeti Fur Cloak!"] = "Moi, le Grand Bartolo, je confectionnerai pour vous ma fameuse cape en fourrure de yéti, célèbre dans le monde entier, et qui fait la renommée de l'Alliance !",
    ["If the \"Collector\" is taking gold from our mines then he's stealing from the kingdom! Bring the Collector to justice, and bring me the ring mentioned in the pickup schedule you gave me."] = "Si le \"Collecteur\" prend de l'or dans nos mines, il le vole au royaume ! Traînez-le devant la justice et apportez-moi l'anneau dont parlait le Plan de route que vous m'avez donné.",
    ["If you want Bonescythe made, you're going to have to supply the materials."] = "Si vous voulez que je fabrique de la faucheuse d'os, vous allez devoir me fournir les ingrédients.",
    ["If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it. She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere."] = "Si vous étiez assez aimable de porter la relique à ma femme Vestia, je vous en serai très reconnaissant. Elle n'est pas seulement une excellente prêtresse, elle fait également partie des meilleurs érudits que vous puissiez trouver.",
    ["Ilkrud Magthrull. Yes, I have knowledge of him. He is a powerful orc warlock that makes his residence at the Fire Scar Shrine, a place of great evil in southwestern Ashenvale."] = "Vous méritez bien une récompense pour tout ce que vous avez accompli. Retournez voir Delgren et dites-lui qu'Athrikus Narassin gît à terre par vos soins et que le Culte de la Rive noire est vaincu et démantelé.",
    ["Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin."] = "Imprégner les armes de l'esprit des miniatures est un processus difficile. Maintenant que nous avons les matériaux nécessaires et les miniatures des créatures que vous avez capturées, je peux commencer.",
    ["In Timbermaw, we are content. We do not like strangers. This is good for us, but it is bad for trade. Not long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak."] = "À Grumegueules, nous sommes satisfaits d'être entre nous. Nous n'aimons pas les étrangers, ce qui n'arrange malheureusement pas le commerce. Il n'y a pas longtemps, une de nos rares amis elfe de la nuit est arrivée à Grumegueules, portant une cape en étoffe runique. L'étoffe runique est un textile que l'on ne voit pas souvent par ici, et mes frères ont été séduits par sa perfection.",
    ["In Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death."] = "Hmm… Maintenant que j'y pense, il y a peut-être quelque chose que vous pourriez faire pour la Main. Oui, vous pourriez aider Jes'rimon, c'est sûr.",
    ["In a cave along the southern bank of the lake, a timberling named Oakenscowl is spreading corruption to all the creatures that make Lake Al'Ameth their home."] = "Dans une caverne le long de la rive sud du lac, un sylvain nommé Froncechêne propage la corruption parmi les créatures qui vivent au lac Al'Ameth.",
    ["In northern Winterspring, great cats assemble around a large landmark called Frostsaber Rock. The leader of these cats is known by the name Shy-Rotam."] = "Au nord du Berceau-de-l'Hiver, de grands félins se rassemblent à un endroit appelé le roc des Sabres-de-Givre. Leur chef est connu sous le nom de Shy-Rotam.",
    ["In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence."] = "En préparation d'un assaut sur Ombrecroc, deux Traqueurs noirs ont été envoyés au donjon pour réunir des renseignements.",
    ["In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious..."] = "Le Fléau est une menace persistante pour l'Alliance, vous le savez fort bien. Récemment, nous avons découvert quelque chose, <name>.",
    ["In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya."] = "À la suite des batailles au Puits d'éternité, j'ai appris qu'Ameth'Aran avait été détruit, et son peuple tué, y compris mon bel amour Anaya.",
    ["In the dark times after the fall of the Gurubashi Empire, Zandalar predators used their prowess to provide sustenance for the tribe."] = "Dans les jours sombres qui ont suivi la chute de l'empire Gurubashi, les prédateurs zandalar ont utilisé leurs pouvoirs pour nourrir la tribu.",
    ["Indurium has an amazing resistance to heat! I'm sure it will work for Fizzle's pistons."] = "L'Indurium est étonnamment résistant à la chaleur. Je suis certain que ce métal serait idéal pour les pistons de Fizzle.",
    ["Indurium has an amazing resistance to heat! I'm sure it will work for Fizzle's pistons. But he'll need true indurium ore, not just the flakes."] = "L'Indurium est étonnamment résistant à la chaleur. Je suis certain que ce métal serait idéal pour les pistons de Fizzle. Mais il lui faudra du minerai d'Indurium naturel, pas uniquement quelques paillettes.",
    ["It has become obvious that we cannot ensure that Blacklash and Hematus will remain imprisoned in Lethlor."] = "Il est devenu évident que nous ne pouvons plus garantir que Cinglenoir et Hematus resteront prisonniers à Lethlor.",
    ["It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."] = "Nous pensons qu'à l'origine, les épaulières ornées que portent les races mortelles étaient une tentative pour imiter les ailes des dragons.",
    ["It makes them go berserk! Bring me 8 idols - I want to study them, and I want them out of Trogg hands!"] = "Récemment, juste avant que les troggs ne débarquent sur le site, nous avons découvert un grand nombre d'étranges idoles taillées. Mais nous n'avons pas eu le temps de les étudier, car les troggs nous ont chassés des ruines juste après !",
    ["It took a long time, but I found Reethe. He hide good for a human. Ogron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him."] = "Cela a pris du temps, mais j'ai trouvé Reethe. Il se cache bien pour un humain. Ogron se demande s'il n'est pas devenu fou après tout ce temps passé dans le marais. Vous venez avec moi pour lui tirer les vers du nez.",
    ["It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color."] = "C'est le savoir de l'un des plus puissants Bien-nés qui a créé le sceau fermant ma prison. À Ameth'Aran, dans les ruines au sud, jumelles de celles-ci, brûle une flamme antique, de couleur bleue.",
    ["It's going to be tough going here if I can't manage to scrounge up some materials to construct some defenses and other necessities. I've noticed that the ogres in the area seem to be well equipped with scrap metal."] = "Cela va devenir difficile de se rendre ici si je ne peux pas me procurer du matériel pour construire des défenses et les choses nécessaires. J'ai remarqué que les ogres de la région semblaient bien équipés en morceaux de métal.",
    ["It's no secret that the trademark of the Defias Gang is their Red Bandanas. But we've learned that the material from which these bandanas are made signifies the member's rank."] = "Ce n'est un secret pour personne que le signe de reconnaissance du gang des Défias est un masque rouge. Mais nous avons appris que la qualité du tissu dont est fait le masque détermine le rang de celui qui le porte au sein du gang.",
    ["It's so cold, now. The Plague of Undeath crawls through my veins like an icy serpent. The Mindless State will be upon me soon. But no doomed destiny will prevent me from serving our Dark Lady."] = "Il fait si froid maintenant. Le Fléau mort-vivant brûle dans mes veines comme un serpent de glace. Mon âme sera bientôt perdue. Mais aucun destin, aussi irrévocable soit-il, ne m'empêchera de servir la Dame noire.",
    ["It's terrible. We are not going to have enough parts to get our fleet of gyrodrillmatic excavationators to Dun Morogh. What we need are spare parts."] = "C'est affreux, <name>. Nous n'avons pas suffisamment de pièces détachées pour notre flotte d'excavateurs gyrodrilmatiques à Dun Morogh. Nous avons besoin de ces pièces, <name>.",
    ["It... It... It was all a trap. Forgive... me. Kill the bastard... Kill him for us... for Thorius."] = "C'était... C'était... C'était un piège. Oubliez... moi. Tuez ce bâtard… Tuez-le pour nous… pour Thorius.",
    ["Just before the invasion I uncovered a large tablet called the Goaz Stone. The translated text breaks off in 4 places. The text speaks of a \"divine plan\" and a \"doomed prophecy.\" I fear we are running out of time."] = "Avant l'invasion, j'ai découvert une tablette appelée la Pierre de Goaz. Elle s'est brisée en quatre morceaux. Elle parle d'un \"plan divin\" et d'une \"prophétie damnée\".",
    ["Just one last thing you must do, soldier. I've taken the liberty of putting Gor'tesh's head on a pike. Now all you have to do is take this head to the top of Dreadmaul Rock and stick it into the ground."] = "Il vous reste une dernière chose à faire, soldat. J'ai pris la liberté de planter la tête de Gor'tesh sur une pique. À présent, tout ce que vous avez à faire, c'est d'apporter cette pique au sommet du rocher des Cognepeurs et de la ficher dans le sol.",
    ["Just recently, a large band of nomadic ogres arrived in Tanaris. South of here, they have taken over a large area of the desert and formed a compound."] = "Encore récemment, une grande bande d'ogres nomades est arrivée à Tanaris. Au sud d'ici ; ils se sont arrogés une importante zone du désert et ont formé une base.",
    ["Kill me. Before it's too late. I am Hameya. While traveling to Zul'Mashar, my brethren and I ate some bad meat... and we changed. We are infected."] = "Tuez-moi. Avant qu'il ne soit trop tard. Je suis Hameya. Tandis que je voyageais vers Zul'Mashar, mes frères et moi avons mangé de la viande corrompue... et nous avons changé. Nous sommes infectés.",
    ["Kroshius lays in a heap to the northeast, in the Shatter Scar Vale. Take this Fel fire and use it on his remains. The fire should reanimate the fallen infernal."] = "L'Infernal Kroshius gît en tas au nord-est, dans le Val Grêlé. Prenez ce Gangrefeu et utilisez-le sur ses restes. Cela devrait le ranimer.",
    ["Kurzen may be dead, but...that which drove him to evil still lives! Through my studies I have discovered this: An Ogre Mage - Mai'Zoth - dwells in an Ogre Mound within the eastern mountains of Stranglethorn."] = "Kurzen est peut-être mort, mais… ce qui l'a conduit vers le Mal existe toujours ! Mes recherches m'ont appris ceci : un ogre mage du nom de Mai'Zoth vit dans les monts orientaux de Strangleronce.",
    ["Legend states that their ancient robes never looked the same twice. I will give you an illusionist's robe..."] = "Notre puissance et notre rang au sein de la tribu sont indiqués par ce que nous portons. Nos tenues sont faites à partir des matériaux les plus fins, et imprégnés du mojo dont nous nous servons pour devenir puissants.",
    ["Let me to be frank with you. I'm interested - nay, concerned with why the Arch Druid in Darnassus is using the name of the Cenarion Circle as well as the Circle's resources to procure vast amounts of morrowgrain."] = "Je vais être franc avec vous, <name>. Cela m'intéresse – non, cela m'inquiète !",
    ["Like many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk's mate by the Vilebranch."] = "Comme bien des gens dans notre village, j'ai perdu un être cher. Malkhor, mon frère jumeau, a été pris dans le même raid des Vilebranch que le compagnon de Torntusk.",
    ["Limiting the number of Bloodfury Harpies will not be enough. The only true cure for their disease would be to slay their leader, Bloodfury Ripper!"] = "Tailler dans les rangs des Rougefuries ne sera pas suffisant en soi. Le seul véritable remède à cette infestation serait d'exécuter leur chef, la créature appelée la Déchiqueteuse Rougefurie !",
    ["Listen well. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue."] = "Écoutez bien, <name>. Bien que les quatre tours ne pourront jamais être détruites, vous pouvez vous servir de la Torche de châtiment afin d'y mettre le feu pour une longue période.",
    ["Listen, that ring is yours, sure..."] = "Écoutez, <name>, cet anneau vous appartient mais je peux l'améliorer.",
    ["Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep. And not only was it pretty--it held great power for those with the knowledge to use it."] = "Il y a longtemps, je possédais une splendide pièce de joaillerie, la tiare des abysses. Elle n'était pas seulement belle, elle détenait un grand pouvoir, pour ceux qui savaient l'utiliser.",
    ["Look at what has happened to this place! These lands were once occupied by good farm folk. But the damned thieves have driven them all off. Not me, though!"] = "Regardez ce qu'il s'est passé ici ! Ces terres étaient autrefois habitées par de braves fermiers. Mais ces maudits voleurs les ont tous chassés. Pas moi, pour sûr !",
    ["Lower your voice. The Kolkar centaurs lie just over the ridge to the west in Kolkar Crag."] = "Parlez plus doucement, <class>. Les centaures kolkar sont juste derrière la crête, à l'ouest, dans la combe des Kolkar.",
    ["Malcin claims he is outside Razorfen Downs. This ambassador must be slain--his mission a failure in the eyes of the Lich King."] = "Madame, Vous savez exactement ce que nous sommes en train d'offrir. L'opportunité de prendre les Tarides et les terres au-delà n'est pas à négliger.",
    ["Many a hunter is attracted to Loch Modan to hunt our famous crocs. There are always merchants who seek out crocolisk skins for clothing items or armor, and there are also some who enjoy the taste of their meat."] = "Beaucoup de chasseurs viennent au Loch Modan pour chasser nos fameux crocilisques. Il y a toujours des marchands qui payent pour avoir ces peaux servant à la confection de vêtements ou d'armures ; sans parler de ceux qui apprécient leur viande.",
    ["Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with..."] = "Beaucoup de membres de la Légion offrent des cadeaux à leurs disciples, comme vous le savez peut-être. La Dame noire estime que certains de ces cadeaux seraient mieux placés entre ses mains plutôt qu'entres celles de ceux doués de… moins de vision.",
    ["Many of my friends perished that horrible day when the mine tunnel caved in. If your adventures happen to bring you into that wing of the mine in Moonbrook, please keep an eye out for any sign which might identify them."] = "Nombre de mes amis ont péri ce jour terrible de l'effondrement de la mine. Si vos pas vous conduisent dans cette partie de la mine de Ruisselune, voyez s'il existe des indices qui permettraient de les identifier.",
    ["Many of my soldiers died in the battle of Dun Modr. My own brother perished when the West Bridge over the Thandol Span was destroyed. Aye, the Dark Iron dwarves are a devilish breed."] = "Beaucoup de mes soldats sont morts à la bataille de Dun Modr. Mon propre frère a péri lors de la destruction du pont de l'ouest du viaduc de Thandol. Oui, les nains Sombrefer sont une race diabolique.",
    ["Master Mazen's directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep. But I had never been to the Blasted Lands before!"] = "En tant que conservateur de la bibliothèque de l'Académie des arts et sciences des arcanes, il est de ma responsabilité de m'assurer que tous les livres magiques et les parchemins sont bien présents. Qui sait quelle folie pourrait survenir si l'un de ces textes enchantés tombait entre de mauvaises mains ?",
    ["Maybe it'll even help protect you from the coming atrocity that is Lotwil's newest invention. I've been working with all the extra stones you collected for him, and I can make some nice bracers that you might want to use."] = "Je sais à quel point Lotwil peut faire preuve de mesquinerie, <name>, aussi laissez-moi vous confectionner quelque chose en échange de tous vos efforts. Cela vous protégera peut-être même de l'atrocité imminente qu'est la nouvelle invention de Lotwil.",
    ["Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate."] = "Moi et d'autres guerriers avons été envoyés par le Chef de guerre pour récupérer un objet à Durnholde et enquêter sur ce prétendu Syndicat.",
    ["Mellifluous liquid clear as a baby's tears Turns a lovely deep amber over the years But before we proceed to get lit to the hilt A barrel of charred oak must be built."] = "Douce eau aussi translucide que des larmes d'enfant Une merveilleuse et profonde couleur ambre prend avec le temps Mais avant de nous saouler Un fût de chêne doit être fabriqué.",
    ["Mirah Chandler's song, given for finishing a chain of favours in the Barrens -- the reward players remember long after they forget the errands."] = "Et voilà, <name>.",
    ["Morbent Fel hides in his lair, the house perched atop the hill to the east overlooking the Raven Hill cemetery. His time in this land is drawing to an end..."] = "Morbent Fel se cache dans son repaire, la maison perchée sur la colline à l'est, celle qui domine le cimetière de Colline-aux-Corbeaux. Son temps sur cette terre touche à sa fin...",
    ["Mud big ogre. Me hungry. Go bash fishy. Bring Mud food. You feed Mud or Mud eat you."] = "Pil'bou grand ogre. Moi faim. Aller taper poisson. Apporter manger pour Pil'bou. Vous nourrir Pil'bou sinon Pil'bou manger vous.",
    ["Murlocs are becoming a problem. Larger groups of the fishmen are dropping anchor along the shores of Lake Everstill and fishing up a storm!"] = "Les murlocs sont en train de devenir gênants. De plus en plus de pêcheurs jettent l'ancre au large des rives du lac Placide et remontent un problème dans leurs filets !",
    ["My brother Quinn and I were tasked to recon Silverpine Forest and report to High Executor Hadrec. But we didn't get far -- when moving through this farm we were attacked by the ghoul Ivar the Foul."] = "Mon frère Quinn et moi avions pour mission de reconnaître la forêt des Pins argentés et de rendre compte au Grand exécuteur Hadrec. Mais nous ne sommes pas allés loin.",
    ["My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another."] = "Mon frère Ribbly a toujours été une sangsue pour ma famille, en prenant son argent et en le gâchant dans des projets tous plus stériles les uns que les autres.",
    ["My brother Senir and I were sent to different parts of Dun Morogh to investigate the threat posed by the trolls. The Senate has its hands full with the troggs, so they've no need for further annoyances."] = "Mon frère Senir et moi avons voyagé dans tous les coins de Dun Morogh pour évaluer la menace posée par les trolls. Le Sénat est déjà débordé par les ennuis que causent les troggs, il n'a pas besoin de ce problème supplémentaire.",
    ["My brother and I run the poison operations out of the manor Ravenholdt."] = "Mon frère et moi nous occupons de tout ce qui concerne les poisons en dehors du manoir de Ravenholdt.",
    ["My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies. Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life."] = "Ma camarade de clan, Mura Runetotem, est partie pour les Pins argentés afin d'aider nos alliés morts-vivants. C'est une forêt qui dépérit doucement, et elle avait l'espoir d'y insuffler la vie à nouveau.",
    ["My delvings into the Mosh'aru Tablets bear grim news. Hakkar's true form, the god himself, can be born again through the very egg into which you captured him."] = "Les tablettes Mosh'aru contiennent de mauvaises nouvelles, <name>. La véritable forme d'Hakkar, le dieu lui-même, peut renaître par l'intermédiaire de l'œuf dans lequel vous l'avez enfermé.",
    ["My duties include tending to our wounded warriors, tailoring armor and clothes, and assisting Shadow Priest Sarvis with whatever else he might need."] = "Je soigne nos guerriers blessés, j'adapte leurs armures et vêtements, et j'assiste le prêtre des ombres Sarvis.",
    ["My former mentor in the Stormwind city guard sent a message to me that Alliance High Command is becoming concerned with the threat posed by the naga."] = "Mon ancien mentor à la garde de la cité de Stormwind a envoyé un message me disant que le Haut Commandement de l'Alliance commence à s'inquiéter du problème posé par les nagas.",
    ["My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills."] = "Mon ami et camarade Mori Hildelve, qui est Sapeur, a disparu dans les collines.",
    ["My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite."] = "Mon grand-père m'a conté sa bataille avec la créature nommée Mazzranache. Il m'a parlé de ses yeux rouges, démoniaques, de ses serres aiguisées comme des rasoirs et de sa morsure venimeuse.",
    ["My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that."] = "Mon journal ! Ils l'ont emporté dans la caverne. Celui qui l'a pris ? C'était une grosse brute avec d'étranges inscriptions sur la peau et le visage. Je n'ai pas pu regarder plus précisément.",
    ["My pet is almost done. Now I just need something to stuff it with. Only the voodoo feathers from the trolls in the sunken temple will do. They go by the names Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro."] = "Mon familier est pratiquement terminé. Il ne me manque plus que quelque chose pour le rembourrer. Seules les plumes vaudous des trolls du Temple englouti conviendront. Ces trolls s'appellent Balafreur, Mijan, Zolo, Hukku, Zul'lor, et Loro.",
    ["My philosophy on leatherworking is that the work must be the best quality possible - no compromises. Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!"] = "Je suis fier de mon travail et je sais que cela se voit : la qualité ne doit jamais être dévalorisée. Quiconque dit que la qualité n'est pas primordiale ferait également croire que les abysses sont lumineux.",
    ["My physical being ceased functioning after an hour of this torture. The beast then ripped my wedding nose-ring off of my face and stuck it on his finger."] = "Tout mon régiment a été capturé, <name>. Tous ont été tués, sauf moi.",
    ["Naralex had a noble goal. Our great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was."] = "Naralex poursuivait un noble but. Notre grand chef aspirait à entrer dans le Rêve d'émeraude pour faire reverdir ces terres arides, qui étaient autrefois une forêt luxuriante.",
    ["Negolash is a hungry giant. When the giants destroyed our ship, Negolash went straight for my kitchen. He wasn't hungry for crew like the other giants."] = "Negolash est un goinfre. Quand les géants ont détruit notre navire, il est venu directement dans ma cuisine. Il n'avait pas faim d'hommes d'équipage comme les autres géants.",
    ["No, no, no - I'm not all of the sudden saying that the ring is mine."] = "Non, non, non, je ne suis pas en train de dire que cet anneau est à moi.",
    ["Normally I put forth a small challenge to followers of the Light to test their skill."] = "Il est de coutume de tester l'un de vos pouvoirs pour savoir si vous êtes digne de porter les robes qui symbolisent votre place dans l'Eglise.",
    ["Nothing like a day of boar hunting, eh? Though, here in Coldridge Valley, there are so many boars it almost takes the fun out of it. No need to get them charging."] = "Rien de tel qu'une journée de chasse au sanglier, pas vrai ? Oui, eh bien ici, dans la vallée des Frigères, il y en a tellement que ça gâche tout plaisir. Pas besoin de les pousser à attaquer !",
    ["Now is the time to assault the Scourge's place of strength in Silverpine: Fenris Isle. You must again go to the Isle and destroy Thule Ravenclaw."] = "Il est maintenant temps d'attaquer le bastion du Fléau dans les Pins argentés : l'île de Fenris. Vous devez aller sur l'île et tuer Thule Ravenclaw.",
    ["Now it is time to capture the essence of the avatar of Hakkar. Take the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth."] = "Maintenant il faut capturer l'essence de l'avatar d'Hakkar. Apportez l'Oeuf d'Hakkar au Sanctuaire du dieu déchu dans le Temple englouti d'Azeroth.",
    ["Now that I have the spiders' venom, I'd like some live specimens to study. Unfortunately, capturing a living, giant spider is more than I can ask of you, young."] = "À présent que j'ai le venin de ces araignées, j'aimerais étudier des spécimens vivants. Malheureusement, capturer une araignée géante est plus que je ne peux vous demander, jeune <class>.",
    ["Now that I've finished copying the book, here's the original Stresses of Iron. Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay."] = "Maintenant que j'ai fini ma copie des « Tensions du fer », je vous rends l'original. Merci pour votre patience et si vous voyez Milton, dites-lui que je suis désolé pour ce long retard.",
    ["Now that my crop is saved, take this Grape Manifest to Brother Neals. He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes."] = "À présent que mes vendanges sont sauvées, apportez ce Manifeste des vendanges à Frère Neals. Il s'occupe du magasin de nourriture et de boisson de Northshire, et il est certain qu'il sera ravi d'apprendre que nous avons du raisin frais.",
    ["Now that the catapults have been burned, find and kill Chieftain Nek'rosh."] = "Maintenant que les catapultes ont été détruites, trouvez et exécutez le Chef Nek'rosh.",
    ["Now that you have gathered Bloodscalp trophies, I have another task for you. The Skullsplitter tribe of trolls live to the southeast, and for years we have warred with them."] = "À présent que vous avez collecté les trophées des Bloodscalp, j'ai une autre tâche pour vous. La tribu des trolls Skullsplitter vit au sud-est, et nous sommes en guerre contre eux depuis des années.",
    ["Now that you scared the centaur clans, it's time to bleed them. When traveling Desolace, hunt centaur. I don't care which clan you hunt. Just gather ears."] = "Le peuple des centaures est divisé en nombreux clans. Chaque clan a son chef et ses propres buts, mais ils ont tous une « qualité » en commun : la cruauté. Si nous voulons avoir une chance de construire la paix, alors les centaures doivent être éradiqués. C'est exactement la tâche que je vous confie.",
    ["Now that you've had a taste of the Crushridge ogres, I want you to really bloody their noses... Go into the Ruins of Alterac and seek out the Crushridge Warmongers."] = "Maintenant que vous avez eu un avant-goût des ogres Cassecrête, je veux que vous leur rentriez dedans franchement... Allez dans les ruines d'Alterac et débusquez des Combattants Cassecrête.",
    ["Now the time has come to save the Druids of the Talon. If we fail now, they will be forever lost in sleep. I shall prepare the Relics of Wakening and perform the ritual."] = "Le temps est venu de sauver les druides de la Serre. Si nous échouons maintenant, <name>, ils resteront à jamais captifs de leur sommeil. Je pourrais préparer les Reliques d'éveil et pratiquer le rituel, mais mon travail ne peut prendre effet tant que le responsable de cette horrible situation est en vie.",
    ["Now there is just one more item needed to complete this device. Cog's blueprint calls for a lens of some sort. The only lens I know of that would be large enough will be very difficult to acquire."] = "Il ne manque plus qu'un seul objet pour terminer cet appareil. Le plan de Cog mentionne une lentille ou quelque chose comme ça. La seule lentille qui soit assez large pour l'appareil risque d'être très difficile à acquérir.",
    ["Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest."] = "Maintenant vous devez finir la tâche qui vous a été confiée. Prenez les Filières d'argent et offrez le sacrifice de dame Sathrah à Elune.",
    ["O'Breen led the ships into the cove. We were certain this is where the treasure could be found. The Harbinger docked safely but as the Maiden's Folly and Spirit of Silverpine approached the tides began to lower."] = "O'Breen a conduit les bateaux dans la crique. Nous étions certains d'y trouver le trésor. Le « Noir messager » a accosté sans encombre, mais à mesure que la « Folie de la vierge » et « L'Esprit des Pins argentés » approchaient, le niveau de la mer a commencé à baisser.",
    ["Off the coast of Darkshore to our north are two wrecked ships - the Silver Dawning and the Mist Veil. Some time ago, both ships ran afoul of the blasted murlocs as they sailed across the vast sea into Auberdine."] = "Au large de Sombrivage, plus au nord, il y a deux épaves de bateau : l'Aube argentée et le Voile de brume. Il y a quelque temps, ces deux bateaux sont tombés sur ces maudits murlocs, alors qu'ils faisaient voile à travers la vaste mer jusqu'à Auberdine.",
    ["Oh my! Oh my! There is a doom approaching. Mark me! A doom! No, I cannot speak of it...cannot utter their names or they may hear me! But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them!"] = "Oh dieux ! Une malédiction approche. Écoutez-moi ! Une malédiction ! Non, je ne peux pas en parler... je ne peux pas prononcer leur nom, ils pourraient entendre ! Mais si vous voulez savoir, oui si vous voulez en savoir plus sur eux...",
    ["Oh, you know what? That reminds me. You wanna finish up a little job I took up while I was in Tanaris? It's easy... Krinkle Goodsteel in Gadgetzan was lookin' for some stuff found here in Searing Gorge and a few other places."] = "Oh, maintenant que j'y pense... Comme je suis bloqué ici, vous pourriez peut-être finir un petit travail que j'avais commencé quand j'étais à Tanaris. C'est facile, enfin vu de l'extérieur ça paraît facile. Krinkle Goodsteel à Gadgetzan recherchait du matériel que l'on peut trouver ici, dans la Gorge des Vents brûlants et dans quelques autres lieux. Vous pourriez peut-être jeter un coup d'oeil à cette liste et lui apporter ce qu'il veut ?",
    ["Oh...the flowers are blooming in Hillsbrad and the air is so fresh and brisk. I can't help but to wallow in the misery of it all. I look out my grimy window and long for the day when our New Plague brings this world the death it deserves."] = "Oh ! <name>… Les fleurs s'épanouissent à Hillsbrad et l'air est si pur et vif... Comme cela est triste et regrettable.",
    ["Ok, everything is prepared and packed and ready for transport! Good luck in your journey, and make sure you tell Tinkee that she owes me!"] = "Bien tout est prêt, empaqueté et paré au transport. Bonne chance dans votre voyage, et n'oubliez pas de rappeler mon dévouement et ma loyauté à Tinkee !",
    ["One of Onyxia's own teeth, taken after she was finally dragged out of Stormwind's court and killed in her lair."] = "Le seigneur Runthak attend votre arrivée dans la vallée de la Force.",
    ["One of Zandalar's legendary madcaps was Khar'vaxal the Cracked."] = "Khar'vaxal le Fêlé fut l'un des insensés les plus fameux qu'aient comptés les Zandalar.",
    ["One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep."] = "L'un de mes éclaireurs les plus observateurs me rapporte que les épaves de la flotte de Proudmoore sont toujours près de la côte de Durotar, juste à l'est du donjon de Tiragarde.",
    ["One of my scouts witnessed an attack on a caravan from Durotar. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout."] = "L'un de mes éclaireurs a été témoin d'une attaque sur une caravane en provenance de Durotar, <name>. Les coupables sont effectivement des hurans de la tribu Tranchecrin. L'un d'eux en particulier dirige les attaques : Kreenig Grondegroin.",
    ["One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power."] = "Un de nos plus gros problèmes est d'obtenir les ressources nécessaires à notre survie. L'or était déjà rare lorsque l'Alliance était au sommet de sa puissance.",
    ["Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch. Make haste to Wyrmbog in the south of Dustwallow Marsh."] = "Le village des Cognepierres a été envahi par la portée d'Onyxia. Mais pourquoi la fille d'Aile de mort, le seigneur du vol noir, est-elle descendue sur nos champs ? C'est très troublant.",
    ["Our initial scouting reports of Silverpine show the rot hides have a base at an old farm to the north, the Dead Fields."] = "Nos premiers rapports de reconnaissance dans la forêt des Pins argentés indiquent que les Poils-putrides ont une base dans une vieille ferme, le Champ des morts.",
    ["Our power comes from darkness and shadow, but that is not your only role. You have acknowledged that there is merit in knowing the healing arts."] = "Notre pouvoir vient des ténèbres et de l'ombre, <name>, mais ce n'est pas tout. Vous avez reconnu qu'il était intéressant de connaître les arts de la guérison.",
    ["Out here in the wilderness, Kindal and I have meager means to reward your help, but we don't want you to feel unappreciated. Take my signet ring."] = "Ici, dans les terres sauvages, Kindal et moi n'avons pas grand-chose à vous offrir, mais nous voulons récompenser votre aide. Prenez ma chevalière.",
    ["Overlord Runthak awaits your arrival in the Valley of Strength. Do not keep your public waiting, hero."] = "Le seigneur Runthak attend votre arrivée dans la vallée de la Force. <Thrall vous salue.> Ne faites pas attendre votre public, héros.",
    ["Past the Argent Dawn encampment of Light's Hope and west of Northdale, you will find the corpulent maggot beast, Borelgore. I've lost entire regiments to that monster."] = "Devant le campement de l'Aube d'argent appellé Espoir de Lumière, à l'ouest de Valnord, vous trouverez une énorme larve, Creusechair. J'ai perdu des régiments entiers contre ce monstre.",
    ["Perhaps you know the pain of uncertainty, perhaps not. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters."] = "Connaissez-vous l'affliction du doute, <class> ? Sachez seulement que je suis là toute la journée à scruter l'horizon pour repérer ces monstres.",
    ["Please help! These creatures are going to eat me! Help me out of here, and I'll give you a great treasure! It's in my camp in the swamp north of Stonard, but it's locked in a strongbox that can be opened through a trick that only I know."] = "Au secours ! Ces créatures vont me manger ! Sortez-moi de là, et je vous donnerai un grand trésor ! Il est dans mon camp, dans le marais au nord de Stonard, mais il est enfermé dans un coffre qui ne peut être ouvert que grâce à un truc que moi seul connais.",
    ["Please, return to Duthorian and let him know that I'm safe for now. I have you and the Church to thank for that. He'll send word to Ironforge to let my Jordan know that he has nothing to fear."] = "Je suis sûre qu'ils seront là dans peu de temps maintenant, préparez-vous. J'ai une arme à la maison. Je vais la chercher et je reviens vous donner un coup de main, mais vous allez devoir faire le plus gros du travail j'en ai peur.",
    ["Please, take from this a relic of old. We no longer have a use for the item. May it serve you well in your fight against the legion."] = "Je vous en prie, prenez cette Relique des Anciens. Nous n'en avons plus besoin. Puisse-t-elle bien vous servir dans votre combat contre la Légion.",
    ["Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was. We must not let their valiance go for naught. This crone... Charlga Razorflank..."] = "Pauvre Heralath ! Et ce nain... Lonebrow. Quel esprit courageux il avait. Nous ne devons pas laisser leur vaillance périr pour rien. Cette mégère… Charlga Trancheflanc… doit être arrêtée. Il ne fait pas de doute qu'infiltrer le Kraal sera périlleux.",
    ["Powerful warrior and awkward novice alike have fallen to the venomous sting of the scorpid. You will find large numbers of scorpids northwest of here."] = "De piètres novices comme de grands guerriers ont succombé au dard venimeux des scorpides. Vous trouverez un grand nombre de ces créatures au nord-ouest.",
    ["Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose."] = "Ouvrir la console de contrôle révèle des entrelacs de fils, de tubes et d'autres objets mécaniques étranges, dont la plupart ne semblent avoir aucune utilité.",
    ["Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon."] = "La magie qiraji est puissante et ancienne. Les Qiraji les plus redoutables manient des objets si terribles qu'ils feraient hésiter un dragon.",
    ["Quite impressive. The crystal of Zin-Malor can never be returned to the temple which, as you know, lies in ruin. But I believe that your effort to undo the evil of the past should not go unrewarded."] = "Impressionnant, <name>. Le cristal de Zin-Malor ne pourra jamais être replacé dans le temple qui, vous le savez, est maintenant en ruine. Mais j'estime que vos efforts pour réparer les méfaits du passé ne doivent pas rester sans récompense.",
    ["Rackmore's log tells of how his ship was sailing for Feathermoon Stronghold when it was attacked by seafaring creatures."] = "Le journal de Rackmore explique comment son bateau a été attaqué par des créatures marines alors qu'il naviguait vers le bastion de Feathermoon.",
    ["Razelikh's lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain."] = "Razelikh se terre sur la plus haute montagne des Terres foudroyées. Le seul moyen d'y accéder est d'utiliser les Runes de téléportation près de la montagne.",
    ["Ready to go? First, we need to get this powder to Ironband. It'll be a lot for me to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for me."] = "Prêt à y aller, <name> ? D'abord, nous devons trouver de l'explosif pour Ironband. Je ne pourrai pas le porter seul, d'autant que ça peut être dangereux – et qui sait ce que les Sombrefer me réservent ?",
    ["Recently, a new group of thieves has been hanging around Northshire. They call themselves the Defias Brotherhood, and have been seen across the river to the east."] = "Un groupe de voleurs traîne depuis peu autour de Northshire. Ils se nomment eux-mêmes la Confrérie défias, et ont été aperçus de l'autre côté de la rivière à l'est.",
    ["Recently, just before the Troggs surfaced within the site, we had uncovered a large number of strange, carved idols. But we didn't have the chance to study them, for soon after their discovery the Troggs chased us away from the ruins!"] = "Récemment, juste avant que les troggs ne débarquent sur le site, nous avons découvert un grand nombre d'étranges idoles taillées. Mais nous n'avons pas eu le temps de les étudier, car les troggs nous ont chassés des ruines juste après !",
    ["Relara's fever has passed, but she is still very weak. I do not believe time alone will give her back the strength she has lost. I believe it will take the power of a moonstone."] = "La fièvre de Relara est tombée, mais elle est toujours très faible. Je ne crois pas que sa force reviendra avec le temps. Il va falloir le pouvoir d'une pierre de lune.",
    ["Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell."] = "Les rapports de mes supérieurs à Brill indiquent qu'un agent de la Croisade a été détaché du Monastère écarlate et envoyé ici, au Glas.",
    ["Return to Belgrom in Orgrimmar. He will want to see her head for himself! We'll return there shortly. Ah, this is indeed a good day. Thank you for your help."] = "Retournez voir Belgrom dans Orgrimmar. Il voudra voir sa tête de ses yeux ! Nous reviendrons bientôt. Ah, c'est en effet une bonne journée. Merci pour votre aide, <name>.",
    ["Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you."] = "Retournez voir ma compagne, l'Aînée Torntusk du village des Revantusk. Dites-lui que je serai bientôt de retour ! Elle ne manquera pas de vous récompenser.",
    ["Return to your own tribe and let them know of your victory here. Show them your trophy, and bask in the glory..."] = "Retournez dans votre tribu pour raconter votre victoire. Montrez-leur votre trophée et appréciez la gloire que vous venez de conquérir…",
    ["Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest. According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew."] = "La Croisade écarlate lance des raids depuis la tour en ruine au nord-est de Tirisfal, au-delà du Repos de Faol. Selon nos informations, elle est menée par le capitaine Melrache qui a la réputation d'être un officier impitoyable.",
    ["Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure! But it remains that I cannot make the trek back to the Den unassisted."] = "<class> ! Je me voyais déjà mort ici, ignoré de tous. Alors que je chassais les scorpides de la vallée, je fus soudain confronté à un spécimen particulièrement puissant. Je parvins à lui porter un grand coup avant qu'il ne referme ses pinces autour de ma jambe.",
    ["Sergeant Bly stole from me! He said he'd only borrow it, but he stole my cherished divino-matic rod!! Without that rod how will I know where to dig new water holes??"] = "Le sergent Bly m'a volé ! Il a dit qu'il ne faisait que l'emprunter, mais il a volé mon bâtonnet divino-matic ! Sans lui, comment savoir où creuser de nouveaux puits ?",
    ["Shadowfang Keep holds a book, the Book of Ur, which would be much prized in my collection. Ur was a great mage of Dalaran before the coming of the Scourge, his studies in other worlds are of much value to..."] = "<name>, il y a un livre dans le donjon d'Ombrecroc, le « Livre d'Ur », qui ferait très bon effet dans ma collection. Ur était un grand mage de Dalaran avant l'arrivée du Fléau, les études qu'il a faites dans certains domaines ont beaucoup de valeur aux yeux de certains...",
    ["Shortly after the fall of the Gurubashi, we Zandalar almost succumbed to a final defeat from evil within our own tribe."] = "Peu après la chute des Gurubashi, nous autres Zandalar avons failli succomber, dévorés de l'intérieur par le mal.",
    ["Small timberlings are sprouting around the waters of Lake Al'Ameth. I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble."] = "De petits sylvains poussent près des eaux du lac Al'Ameth. J'ai bien peur que nous ne puissions plus rien faire pour ces jeunes sujets.",
    ["So excited I am! Three little cages for three little elves! But what shall we do with our lovely tree-hugging friends? Why, let's give them a taste of..."] = "Je suis surexcité ! Trois petites cages pour trois petits elfes ! Mais qu'allons-nous faire de nos trois calinouilleurs d'arbre ? Eh bien !",
    ["So you're looking for an altar of some sort? Well, I'm no expert on troll ruins like my father, but I have heard about a sunken troll city out near that island you're looking for."] = "Ainsi vous recherchez un autel d'un certain genre ? Eh bien !",
    ["So, the time is now then? I appreciate your efforts, and if the situation does not lend itself, then allow me to thank you now for everything you've done for me and my family."] = "Ainsi, le temps est venu ? J'apprécie vos efforts, et si la situation ne se résout pas, alors permettez-moi de vous remercier dès à présent pour tout ce que vous avez fait pour moi et ma famille.",
    ["Something evil is brewing in the forests of Teldrassil. Look long the hills to where the peaceful furbolgs used to dwell. They have deserted their homes and are amassing under the name of the Gnarlpine tribe."] = "Quelque chose de malfaisant se développe dans les forêts de Teldrassil. Allez dans les collines où les paisibles furbolgs avaient habitude de vivre. Ils ont quitté leurs foyers et se regroupent maintenant, sous le nom de tribu des Pins-tordus.",
    ["Stalvan Mistmantle led a life of depravity. Innocent victims died by his hand. Undoubtedly he is guilty of countless crimes. Now the lunatic threatens Darkshire."] = "Stalvan Mistmantle est un dépravé. De nombreuses victimes ont perdu la vie entre ses mains. Il est sans aucun doute coupable d'un nombre incalculable de crimes et de méfaits. Et maintenant ce dément menace Darkshire.",
    ["Stormwind has abandoned us. A foul wind of depravity rustles through the plains of Westfall. This was my homeland and I will not turn my back on the citizens who choose to remain here."] = "Stormwind nous a abandonnés. Un vent de corruption souffle sur la marche de l'Ouest. C'est ma terre natale et je n'abandonnerai pas les gens qui ont choisi de rester ici.",
    ["Such a shame the land is in such shambles. But the Memorial came out quite well!"] = "Ah, Lordaeron fournit une si belle pierre. Il est si dommage que cette terre connaisse une telle confusion.",
    ["Sure enough, deep within the Old Jug there is another clue to Sander's treasure."] = "Bien vu !",
    ["Take Karnitol's things back to Roetten in Ironforge and he'll pay you for a job well done. Haha, if you're not careful, he's gonna be so pleased with ya that he'll ask you to join us full time."] = "Vous prenez un moment pour comprendre comment le coffre a été ouvert, et vous remarquez, sur les côtés et le dessus du coffre, de longues et profondes entailles. Elles révèlent que quelque chose d'autre qu'un humain ou qu'un géant s'y est intéressé.",
    ["Take Lok's head to Thork in the Crossroads. He should know what has happened to my tribe without any words--ha, not that he would believe Mangletooth helped in such things."] = "Apportez la tête de Lok à Thork à la Croisée, <name> <grogne>. Il devrait savoir ce qu'il est advenu de ma tribu sans le moindre mot--ha, mais je ne m'attends pas à ce qu'il croie que Mangletooth y a <grogne> contribué.",
    ["Take this Nether Gem to my old comrade Bethor. It will let us communicate... and I have much to tell him."] = "Portez cette Gemme du néant à mon vieux compagnon Bethor. Cela nous permettra de communiquer… et j'ai tant de choses à lui dire.",
    ["Take this letter back to Stormwind and let Malin know that Kryten an' I'll be home soon. He'll reward you well for helping us here, of that I've no doubt."] = "Apportez cette lettre à Stormwind et informez Malin que Kryten sera bientôt de retour. Il vous récompensera pour nous avoir aidés, <name>, sans aucun doute.",
    ["Take this refined and purified Incendia powder to Thousand Needles and toss it on the sacred fire of life. It is located in the Darkcloud Pinnacle on an isolated needle where they bury their dead."] = "Apportez cette Poudre d'incendia raffinée et purifiée aux Mille pointes et versez-la sur le feu sacré de la vie. Il se trouve sur la Cime de Noir-nuage, sur une pointe isolée où ils enterrent leurs morts.",
    ["Take this sealed commendation to Varimathras in the Undercity."] = "Comme vous avez combattu avec valeur à la bataille d'Hillsbrad, j'ai écrit cette recommandation exaltant vos prouesses au combat, pour que le haut commandement les apprécie.",
    ["Talk to my friend, Furen Longbeard, in the Dwarven District of Stormwind. He's the best shieldsmith you'll ever meet, and he owes me a big favor."] = "Vous avez montré vos talents en relevant le défi de Rethban, <name>. Et je respecterai ma parole.",
    ["Tampering of the timeline by a sinister force - most likely the Scourge - has occurred in Andorhal! I can try to keep the passage of time here intact and mend what has been damaged, but I'll need your help to do so uninterrupted."] = "Une altération du passage du temps par une force sinistre, la Horde très probablement, est survenue à Andorhal ! Je peux tenter de conserver le passage du temps intact ici et réparer ce qui a été endommagé, mais je vais avoir besoin de votre aide pour que je le fasse de manière ininterrompue.",
    ["Targorr the Dread served under Gath'Ilzogg as supreme Executioner. His methods were ruthless, even by filthy orc standards. Men who fought bravely to defend the Kingdom were tortured on his whim."] = "Targorr le Terrifiant a servi sous les ordres de Gath'llzogg en tant qu'Exécuteur suprême. Sa méthode était impitoyable, même selon les standards orcs. Les hommes qui combattaient vaillamment étaient torturés selon ses désirs.",
    ["Thanks again for your help. Here's a bottle of Steamwheedle bilge rum. Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze."] = "Merci de votre aide, <name>. Voici une bouteille de rhum de cale Gentepression. Portez-la à MacKinley et il pourra remballer ses préjugés à propos des alcools de Baie-du-Butin.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Icebane bracers."] = "Grâce à vous et Omarion (qu'il repose en paix), je suis maintenant capable de forger des brassards plaie-de-glace.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Icy Scale gauntlets."] = "Grâce à vous et Omarion (qu'il repose en paix), je suis maintenant capable de confectionner des gantelets glacécaille.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Polar bracers."] = "Grâce à vous et Omarion (qu'il repose en paix), je suis maintenant capable de confectionner des brassards polaires.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Polar gloves."] = "Grâce à vous et Omarion (qu'il repose en paix), je suis maintenant capable de confectionner des gants polaires.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create an Icebane breastplate."] = "Grâce à vous et Omarion (qu'il repose en paix), je suis maintenant capable de forger la cuirasse plaie-de-glace.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create an Icy Scale breastplate."] = "Grâce à vous et Omarion (qu'il repose en paix), je suis maintenant capable de confectionner une cuirasse glacécaille.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Glacial gloves."] = "Grâce à vous et Omarion (qu'il repose en paix), je suis maintenant capable de coudre des gants glaciaires.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Glacial wrists."] = "Grâce à vous et Omarion (qu'il repose en paix), je suis maintenant capable de coudre des poignets glaciaires.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Icebane gauntlets."] = "Grâce à vous et Omarion (qu'il repose en paix), je suis maintenant capable de forger des gantelets plaie-de-glace.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Icy Scale bracers."] = "Grâce à vous et Omarion (qu'il repose en paix), je suis maintenant capable de confectionner des brassards glacécaille.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create a Glacial cloak."] = "Grâce à vous et Omarion (qu'il repose en paix), je suis maintenant capable de coudre une cape glaciaire.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create a Polar tunic."] = "Grâce à vous et Omarion (qu'il repose en paix), je suis maintenant capable de confectionner une tunique polaire.",
    ["That beached creature is not an isolated incident here in Darkshore. There are more along the coastline and even in the water."] = "Cette créature échouée n'est pas un incident isolé, ici à Sombrivage. Il y en a plus le long de la côte et même dans l'eau.",
    ["That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."] = "C'est une histoire stupéfiante, <name> ! Je vous remercie sincèrement. Tous ceux qui ont participé à cette affaire vous expriment leur gratitude.",
    ["That's fascinating! I have always wondered about the truth... Well, you must share this knowledge, definitely! Go to Arch Druid Fandral Staghelm right away -- you'll find him in Darnassus, in the Cenarion Circle."] = "C'est fascinant ! J'ai toujours voulu savoir la vérité... Bon, vous devez faire entendre cette vérité ! Allez tout de suite chez l'archidruide Fandral Staghelm, vous le trouverez à Darnassus, au Cercle cénarien.",
    ["The Agamand Mills area has become a foothold for the Scourge. Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered."] = "Les moulins d'Agamand sont devenus un avant-poste du Fléau. Leur point fort est la crypte de la famille Agamand où leur chef local, un squelette nommé le capitaine Dargol a son quartier général.",
    ["The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war."] = "Les sangliers de guerre apprivoisés du ravin de Roncelame se répandent sur nos terrains de chasse. Ils sont entraînés au combat et rendus agressifs par les hurans Dos-hirsute contre lesquels nous sommes en guerre.",
    ["The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken. Far south of the Barrens lies a land known as Thousand Needles."] = "Les Rougefuries ont été maîtrisées. Mais elles se regrouperont bientôt si nous n'agissons pas. Loin au sud des Tarides se trouve une terre connue sous le nom de Mille pointes.",
    ["The Brackwells have a prize-winning pig, Princess. The sow is HUGE, and she got that way from sneaking over here and eating my veggies! So before she comes to our fields...Princess must die!"] = "Les Brackwell ont un cochon qui a gagné des tas de prix, Princesse. C'est une ENORME truie, que je soupçonne de dévaster mon potager ! Avant qu'elle ne s'intéresse à mes champs...",
    ["The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager. The villains! They don't deserve such a fine brew!, I have a tough task for you."] = "Les nains Sombrefer, dirigés par l'infâme Hurley Blackbreath, ont volé l'une des meilleures compositions des Thunderbrew, la bière Thunderbrew. Les monstres ! Ils ne méritent pas de savourer une telle bière !",
    ["The Defias Front is constantly shifting. I've been following their movements for quite some time now. On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear."] = "Les Défias bougent en permanence. Ça fait un moment que je suis leurs mouvements. J'ai remarqué que nombre des membres du gang portaient un masque en cuir rouge.",
    ["The Defias gang in Northshire wears burlap masks, but the Defias in Elwynn wear linen which I can use to make fine linen goods."] = "Les Défias du Northshire portent de simples masques, mais ceux d'Elwynn portent des masques en lin, une belle matière avec laquelle je pourrais faire de très beaux articles.",
    ["The Demon Seed is a powerful tool for the Burning Legion. It rests in a cave on Dreadmist Peak, above a demonic altar of fire. I have prepared power stones that when placed near the Seed will disrupt its connection to the Legion."] = "La Graine démoniaque est un outil puissant au service de la Légion ardente. Elle repose dans une caverne du pic de Brume-funeste, au-dessus d'un diabolique autel de feu. J'ai préparé des Pierres de puissance qui, lorsqu'elles seront placées près de la graine, couperont sa connexion avec la Légion.",
    ["The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council?"] = "Le Cercle terrestre avait des intentions pures envers nos frères tourmentés. Mais qui connaît les motivations de ceux qui chuchotent aux oreilles du Conseil des Anciens ?",
    ["The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements. They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know."] = "Le Cercle terrestre est un groupe de chamans dédié à l'étude et à la préservation des éléments. Ils en savent plus sur les dieux anciens fous, les vieilles légendes et les savoirs antiques que la plupart des savants de ce monde.",
    ["The Embalmer is a name told in one of our children's stories. He was a kindly alchemist, driven mad by the death of his wife, Eliza. To restore her, he used dark magic to place his own heart within the bosom of his dead spouse."] = "Le nom de l'Embaumeur apparaît dans l'une des histoires que se racontent les enfants. C'était un alchimiste bon et généreux, rendu fou par la mort de sa femme, Eliza. Dans le but de la ressusciter, il utilisa la magie noire et plaça son propre cœur dans la poitrine de son épouse décédée.",
    ["The Gelkis Khan is dead, and now the Maraudine will fall! Kill the Maraudine Khan, Hratha! To face him, blow the horn on the high bluff in the Valley of Spears."] = "Vous nous avez aidés contre les Magram, <name>. À présent, aidez-nous à battre le clan des Maraudine ! Tuez leur chef, le khan Hratha !",
    ["The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops. And so, I have a bounty task for you."] = "Les Kolkar représentent une menace pour les ambitions de la Horde dans les Tarides ; nous devons réduire leur nombre. De fait, j'ai une mission pour vous, en échange d'une récompense.",
    ["The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came."] = "Dans le nord, les fosses communes, au sud-ouest de l'antre de Garren ont été construites pour accueillir les morts de Tirisfal lorsque la Peste frappa la première fois.",
    ["The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong."] = "Les Qiraji et leurs serviteurs manient des objets façonnés dans les matériaux les plus rares et les plus luxueux : des os de créatures anciennes gargantuesques, des pierres précieuses extraites des profondeurs de la terre, des métaux purs et résistants.",
    ["The Razormane quilboars to the south, beyond the Field of Giants, have no skilled blacksmiths from what I am told, but they've apparently started to develop sturdier weapons."] = "Les hurans Tranchecrin, au sud, au-delà du Champ des géants, n'ont pas de forgerons compétents, que je sache.",
    ["The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff. First you must pass the Rite of Strength."] = "Les rites de la Terre-mère sont un passage obligé pour tout jeune tauren qui se respecte, à Thunder Bluff. La première épreuve est le rite de Force.",
    ["The Scourge are trying to form a base at the Agamand Mills. If they do, then they can stage further attacks within Tirisfal. The orders have been given."] = "Les forces du Fléau essayent de construire une base aux moulins d'Agamand. Si elles réussissent, elles pourront lancer d'autres attaques sur Tirisfal. Les ordres sont clairs.",
    ["The Silver Stream Mine to the east ran dry long ago. It was converted by the Miners' League into a storage depot, but now Kobolds have moved in, putting their filthy paws on good, Dwarven tools!"] = "La mine du Ru d'argent à l'est est épuisée depuis longtemps. Elle a été convertie en dépôt de stockage par la Ligue des Mineurs, mais aujourd'hui les kobolds s'y sont installés, et ils mettent leurs pattes sales sur nos bons vieux outils !",
    ["The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn. Slaughter them and bring me their torn murloc fins, and the Stormwind Army will reward you well."] = "L'armée de Stormwind a mis à prix la tête des rôdeurs et des fourrageurs murlocs qui se trouvent à Elwynn. Tuez-les, découpez leurs ailerons et ramenez-les-moi, l'armée de Stormwind vous récompensera.",
    ["The Syndicate in Stromgarde do battle with our contingent of militia there."] = "Le Syndicat de Stromgarde est actuellement en guerre contre la milice.",
    ["The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe."] = "Les Grumegueules sont les seuls furbolgs à avoir résisté à la corruption. Pourtant, de nombreuses races exécutent maintenant tous les furbolgs, sans distinction, sans même prendre le temps de s'assure qu'ils sont amis ou des ennemis.",
    ["The Timbermaw tend to stay to themselves. While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible."] = "Les Grumegueules ont tendance à rester entre eux, <name>. Nous laissons passer ceux en qui nous avons toute confiance, mais nous essayons d'éviter les autres tribus de furbolgs, si cela est possible.",
    ["The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."] = "Les Empereurs jumeaux… Leurs murmures incessants usent peu à peu ma santé mentale. Ils se moquent de moi. Ils savent que je ne peux pas pénétrer plus avant dans leur domaine pour sauver mon frère Arygos.",
    ["The Venture Company has a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold! Please, you must help me!"] = "La KapitalRisk possède un réseau d'opérateurs à travers Strangleronce qui empêche les gobelins durs à la tâche, comme moi, de faire de l'or honnête ! S'il vous plaît, vous devez m'aider !",
    ["The Vilebranch fight with supernatural ferocity. This is due to the foul magical weavings of the Vile Priestess Hexx. Throughout Jintha'alor you will find dark vessels of tainted blood."] = "À cause de la magie impure de la vile prêtresse Maléficia, les Vilebranch font preuve d'une férocité surnaturelle. Dans tout Jintha'alor, vous trouverez des calices ténébreux, pleins de sang corrompu. Ils irradient la magie abjecte de leur dieu sans visage, donnant de la force aux Vilebranch tout en les rendant fous.",
    ["The amount of salve made out of the reagents you brought me is good enough for ten doses. While I work with the village to try and make some more salve, I'd like for you to help us get a head start."] = "La quantité de remède constituée à partir des ingrédients que vous m'avez apportés suffit tout juste pour dix doses, <name>. Pendant que je travaille de concert avec ceux du village pour essayer d'en produire plus, je voudrais vous demander de nous aider à gagner du temps.",
    ["The antidote is ready. Please see that Iverron drinks it. There is something that you should know -- the antidote -- it will only remain viable for 5 minutes."] = "Nous allons pouvoir aider Iverron, je connais un antidote qui devrait combattre le poison. Il me faut cependant quelques ingrédients. Je vais avoir besoin de Champignons jacinthe.",
    ["The augurs of the Zandalar all wear a distinctive chest piece called a hauberk."] = "Tous les augures des Zandalar portent une pièce d'amure caractéristique, un haubert.",
    ["The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show. You'd be wise to hold on to them."] = "Les insignes que vous récupérez à la fin de vos missions tactiques, logistiques et de combat pour le compte du Fort cénarien ne sont pas seulement destinés à faire joli, <name>. Conservez-les soigneusement.",
    ["The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."] = "Les insignes que vous récupérez à la fin de vos missions tactiques, logistiques et de combat pour le compte de l'Imploratrice céleste Corne-fière ne sont pas seulement destinés à faire joli, <name>. Conservez-les soigneusement.",
    ["The confessors of the Zandalar all wear a distinctive mantle, marking them as the preservers of the tribe."] = "Les confesseurs des Zandalar portent tous un mantelet caractéristique, qui indique qu'ils préservent la tribu.",
    ["The crystal caverns of Terramok lie to the west, deep within Maraudon... It is an ancient place with much history. And I am looking to get my hands on some of it."] = "Les Cavernes de cristal de Terramok se situent à l'ouest, dans les profondeurs de Maraudon…C'est un endroit ancien doté d'une longue histoire. Il se trouve que je cherche à mettre la main sur une partie de tout cela, <class>. Des reliques des dieux très anciens gisent toujours derrière les portes géantes.",
    ["The defeated water elemental has left behind a strange water globe. You surmise that the object somehow fed the beast energy. Inside the globe, a putrid-looking form of water sloshes about."] = "Sur l'élémentaire d'eau vaincu, vous trouvez un étrange globe d'eau. Vous avez la nette impression que l'objet a absorbé l'énergie de la créature. À l'intérieur du globe, vous discernez une eau aux reflets malsains.",
    ["The demoniac seeks to embody power outright, not just possess it."] = "Le démoniaque cherche à incarner la puissance, et pas seulement à la posséder.",
    ["The druids built the Talon Den on Stonetalon Peak, where they keep many powerful items. They devised a complex scheme to keep them from falling into the wrong hands."] = "Les druides ont construit l'Antre des Serres dans le pic des Serres-Rocheuses. Ils y conservent de nombreux objets puissants.",
    ["The druids in the Wailing Caverns, the Druids of the Fang, are an aberration. They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams."] = "Les druides des Cavernes des lamentations, les druides du Croc, sont une aberration. Ils appartenaient à un ordre de druides nobles voulant soigner les Tarides, mais ils tentent maintenant de plier cette terre à leurs fantasmes.",
    ["The fight goes well. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings."] = "Tenez-vous tranquille, <class>, et permettez-moi de partager avec vous quelque chose d'important pour notre peuple, mais loin d'être évident. Nous sommes une race fière, et la guerre contre les humains a mis à rude épreuve même la grande patience de Thrall.",
    ["The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead."] = "La première chose à faire sera de tremper un peu ce corps trop tendre. Je pourrais vous envoyer dans les Tarides pour y chasser des kodos ; mais en toute honnêteté, vous nous êtes plus utile <vivant que mort/vivante que morte>.",
    ["The following items have been stolen: *One Dark Iron Tuyere. *One Lookout's Spyglass. A reward is being offered to individuals who find and return these pilfered items."] = "Les objets suivants ont été volés : *Une tuyère en sombre fer. *Une longue-vue de guetteur. Une récompense sera offerte aux individus qui trouveront et rapporteront ces objets dérobés.",
    ["The future is inevitable! We hurl ourselves towards it like falling raindrops to the Great Sea. But perhaps, by studying the past, we can know what to expect and be better prepared for the unknown."] = "L'avenir est inévitable ! Nous nous lançons vers lui comme les gouttes de pluie tombent dans la Grande mer. Mais peut-être qu'en étudiant le passé, nous pourrons savoir à quoi nous attendre pour mieux nous préparer.",
    ["The gems that adorn Qiraji idols would work quite well, as their quality is superior. Bring me the ring and idols and I'll create a powerful ring for you."] = "Les anneaux portés par les lieutenants qiraji accordent, paraît-il, des pouvoirs fantastiques. Les gemmes corrompues qui les ornent pourraient, en théorie, être remplacées par des matériaux plus purs, pour créer des versions non corrompues des anneaux.",
    ["The gnome's voice crackles once again from the robot: \"I need to move OOX-09/HL to an open, safe place so it can begin a lengthy take-off procedure."] = "Le robot émet à nouveau la voix du gnome : \"Je dois déplacer OOX-09/HL dans un endroit dégagé et sûr pour qu'il puisse entamer sa longue procédure de décollage.",
    ["The gnome's voice crackles once again from the robot: \"I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure."] = "Le robot émet à nouveau la voix du gnome : \"Je dois déplacer OOX-17/TN dans un endroit dégagé et sûr pour qu'il puisse entamer sa longue procédure de décollage.",
    ["The gnome's voice crackles once again from the robot: \"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure."] = "Le robot émet à nouveau la voix du gnome : \"Je dois déplacer OOX-22/FE dans un endroit dégagé et sûr pour qu'il puisse entamer sa longue procédure de décollage.",
    ["The grand Isha Awak is lord of these waters. Great is his strength, and solemn his pride. The humans on the coast fear him, for he has consumed many of their number."] = "Le grand Isha Awak est le seigneur de ces eaux. Grande est sa force et solennelle est sa fierté. Les humains de la côte le craignent, car il en a occis beaucoup parmi eux.",
    ["The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed! My family is gone, taken by the plague."] = "La traînée ! La truie ! Kenata vit toujours ; sa famille est riche et prospère tandis que je souffre, comme une Réprouvée que je suis ! Ma famille a disparu, emportée par la peste. Notre domaine a disparu, lui aussi, détruit et brûlé pendant la guerre.",
    ["The head of the beast is ready to be taken off... with great force. You have shown every sign that you are able to help us with this final mighty blow."] = "Votre force ne fait aucun doute, <name>. Voyons ce que vous valez contre un ennemi digne de ce nom. Les Rochepoings sont basés au sud-ouest d'ici, vers le pont des nains, et si je ne me trompe pas, les marteleurs et les magi qui s'y trouvent représenteront pour vous un grand défi.",
    ["The herbs of the Barrens are not quite like herbs in other lands. Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different."] = "Les herbes qui poussent dans les Tarides ne sont pas tout à fait pareilles à celles des autres contrées. Leurs propriétés sont à peu près semblables, mais l'eau des oasis les transforme légèrement.",
    ["The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power."] = "Les envahisseurs Stormpike ne sont pas la seule menace dans la région, soldat. La guerre dans la Vallée se livre sur deux fronts. Les trolls cannibales des Winterax ont leurs propres ambitions.",
    ["The keg fizzles slightly."] = "Le tonnelet pétille légèrement.",
    ["The last report I received from Agmond is troubling, more so now that he's dead! He mentioned that his diggers uncovered \"ancient urns\" at the dig site outside Uldaman."] = "Le dernier rapport que j'ai reçu d'Agmond est inquiétant, d'autant plus qu'à présent il est mort ! Il dit que son équipe a découvert des \"urnes anciennes\" au site de fouilles en dehors d'Uldaman.",
    ["The lifeless hand of the tauren druid clutches a surprisingly healthy looking oaken branch. Examining the branch reveals glyphs of a druidic nature carved into the bark."] = "La main sans vie du druide tauren est agrippée à une branche de chêne d'aspect étonnamment sain. En examinant la branche, vous découvrez des inscriptions de nature druidique gravées dans l'écorce.",
    ["The light slowly fades, the sword Trol'kalar, held within a stone sheath has been released."] = "La lumière s'éteint, doucement, et l'épée Trol'kalar, reposant dans un fourreau de pierre, est libérée.",
    ["The madcaps of Zandalar are similar to rogues, but above all else they embrace madness..."] = "Nos insensés ressemblent aux voleurs, mais avant toutes choses, ils savourent la folie… le chaos… l'imprévisibilité de l'existence.",
    ["The moment the artifact is removed from the Monolith, you feel the energy in the Stave of Equinex begin to fade."] = "Lorsque vous retirez l'artefact du Monolithe, vous sentez que l'énergie du Bâton d'Equinex commence à décliner.",
    ["The moonwell water has revealed that embedded inside the crystal are a few small fragments of bone, as well as half of a jawbone."] = "L'eau du Puits de Lune a révélé que quelques petits fragments d'os ainsi que la moitié d'un maxillaire sont incrustés à l'intérieur du cristal.",
    ["The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you."] = "La magie qiraji est puissante et ancienne. Les Qiraji les plus redoutables manient des objets si terribles qu'ils feraient hésiter un dragon.",
    ["The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of dominance and other minor components by and I'll create a set of powerful boots for you."] = "La magie qiraji est puissante et ancienne. Les Qiraji les plus redoutables manient des objets si terribles qu'ils feraient hésiter un dragon.",
    ["The parchment you found at the Master's Glaive is a page from an ancient text...written by elves!"] = "Le parchemin que vous avez découvert au Glaive du Maître est la page d'un texte ancien… écrit par des elfes !",
    ["The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace..."] = "Le Pendentif ? Bien sûr que vous pouvez l'avoir, prenez-le ! Je ne veux garder de lui aucun souvenir… Laissez-moi tranquille, je ne vous demande rien d'autre.",
    ["The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity. Bring me the desecrated remnants of the departed along with reagents of purification and you shall know faith."] = "<Le père Montoy fait quelques gestes étranges dans l'air, devant vous.> Soyez <béni mon fils/bénie ma fille> ! Avez-vous trouvé les habits des défunts ?",
    ["The prison is ready. Now for the most difficult portion of this task. You must find and capture a Doomguard Commander within the Tainted Scar using this crystal prison."] = "La prison est prête, mais le plus difficile reste à faire. Vous devez trouver un Commandant de la garde funeste dans la Balafre impure, puis le capturer grâce à cette prison de cristal. Prenez garde !",
    ["The prized tunic of the Zandalar madcap is no exception, exuding the raw power of chaos and madness that they are able to channel."] = "Mes yeux m'ont abandonné il y a bien longtemps, mais je ne les regrette pas.",
    ["The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion. Perhaps someone in Bloodhoof Village should know of Ghost Howl's demise...."] = "Cette peau déchiquetée de Hurleur fantomatique porte toujours la terrible blessure reçue lors de la bataille des loups contre la Légion ardente. Peut-être quelqu'un au village Bloodhoof sait-il quelque chose au sujet de la malédiction du Hurleur fantomatique...",
    ["The raptors of the Barrens are smarter than raptors in other lands. And I think all that smarts is hiding in their horns!"] = "Les raptors des Tarides sont plus malins que les autres. Et je pense que cette intelligence se trouve dans leurs cornes !",
    ["The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities. The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings."] = "Les anneaux portés par les lieutenants qiraji accordent, paraît-il, des pouvoirs fantastiques. Les gemmes corrompues qui les ornent pourraient, en théorie, être remplacées par des matériaux plus purs, pour créer des versions non corrompues des anneaux.",
    ["The sabercat's fur is a distinctive gray color, blending into the surrounding forest. As she lays there, you observe that she is badly wounded, with deep lacerations across her back and stomach."] = "La fourrure du tigre à dents de sabre est d'un gris particulier, tranchant avec les couleurs de la forêt environnante. Tandis qu'elle repose là, vous remarquez qu'elle est gravement blessée, de profondes lacérations déchirent son dos et son ventre.",
    ["The spiders of the Searing Gorge are an invaluable source of shadow silk. As you know, shadow silk is highly sought after by the artisans of our trade."] = "Les araignées de la gorge des Vents brûlants sont une source inestimable de Soie des ténèbres. Comme vous le savez, la Soie des ténèbres est très recherchée par les artisans de notre métier.",
    ["The survival of our people and lands comes at unfortunate costs. You have spilled the blood of nature's servants; many sick animals you have felled."] = "La survie de notre peuple et de nos terres a exigé des sacrifices, <name>. Hélas, vous avez dû verser le sang des serviteurs de la nature et bien des animaux sont tombés sous vos coups.",
    ["The terrible scorpid, Deathclasp, is believed to have retreated to the southern mountain range in the presence of increased silithid activity."] = "On pense que Poigne-de-mort, la terrifiante scorpide, s'est retirée dans les chaînes de montagnes du sud, en raison de l'activité des silithides, qui s'est intensifiée.",
    ["The thunderhawk, is a fierce beast. It is time for you to face them. You must find where it roams, and bring me its wings as proof of your successful hunt."] = "Le faucon-tonnerre, <name>, est une bête féroce. Il est temps pour vous d'en affronter. Vous devez trouver où il rôde, puis m'apporter ses ailes comme preuve de votre chasse fructueuse.",
    ["The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily."] = "Le trésor repose au fond de la mer depuis si longtemps que les gemmes se sont calcifiées en pierres. Mais le pouvoir contenu dans ces lunettes vous permettront de les localiser facilement.",
    ["The ultimate symbol of a haruspex's power is what they wear."] = "L'ultime symbole de la puissance d'un haruspice réside dans sa vêture, <name>.",
    ["The ultimate symbol of power amongst the tribe is the garb we wear in battle. A demoniac's robes have fused fine runecloth and devastatingly powerful mojo into a single fabric."] = "Le principal symbole du pouvoir au sein de la tribu reste la tenue que nous portons au combat. Les robes d'un démoniaque entremêlent de l'étoffe runique et un mojo d'une puissance dévastatrice.",
    ["The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."] = "L'indicible Dieu très ancien se réveille lentement de son sommeil sous Ahn'Qiraj. Le destin atroce qui attend Azeroth peut s'abattre sur nous dans des jours, ou des années, car le temps n'a pas vraiment de sens pour lui.",
    ["The venom you gathered from the Witherbark's spider god is quite a find! I've been able to kill nearly two dozen rabbits with just a drop of the stuff."] = "Le venin que vous avez récupéré sur le dieu araignée des Witherbark est une grande découverte ! J'ai pu tuer près de deux douzaines de lapins avec une seule goutte.",
    ["The vindicator's symbol of power is the breastplate."] = "Le symbole de la puissance du redresseur de torts est sa cuirasse, forgée d'un puissant mojo.",
    ["The waters of Lake Elune'ara should dissolve the nightmares engulfing this object. Give me a moment to perform the cleansing."] = "Les eaux du lac Elune'ara devraient dissoudre les cauchemars qui noient cet objet. Laissez-moi un moment pour effectuer la purification, <name>.",
    ["The witchdoctor Zalazane dwells on the Echo Isles to the east. They are the isles we once called home. From there he sends his trolls to the mainland, to hex our people and drag more of them under his sway."] = "Le sorcier-docteur Zalazane demeure sur les îles de l'Écho, à l'est. Ce sont les îles que nous appelions autrefois « maison ». De là, il envoie ses trolls sur le continent et déchaîne ses maléfices sur notre peuple pour placer davantage des nôtres sous son emprise.",
    ["There are dwarves preparing a dig site to the northwest. They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings."] = "Il y a des nains qui préparent des fouilles au nord-ouest. Ils pensent que la terre abrite des secrets et ils ont raison.",
    ["There is a camp of Deadwood furbolgs directly to our southwest. Corruption permeates the camp, and I wish to put an end to it before they become a problem."] = "Au sud-ouest se trouve un camp de furbolgs Mort-bois. Il empeste la corruption, et je veux que ce soit résolu avant de devenir un problème.",
    ["There is a green drake deep in the sunken temple of Atal'Hakkar by the name of Morphaz. Years ago, he overwhelmed me in a bold ambush and consumed my apprentice whole."] = "Le temple englouti d'Atal'Hakkar abrite un drake vert nommé Morphaz. Il y a des années de cela, il m'a tendu une embuscade et a dévoré mon apprenti avant que j'aie le temps de mettre mes défenses en place.",
    ["There is a malevolence growing in the timberlings. We are trying to find the source, but until we do...in order to keep Teldrassil safe we must cut down the timberlings who are beyond help."] = "Une maladie décime les sylvains. Nous essayons d'en trouver la cause, mais tant que nous n'y parvenons pas nous devons arracher les sylvains contaminés, pour la sécurité de Teldrassil.",
    ["There is but one final reagent needed to complete the enchantment. In the south, towards the western coast, high above the bluffs, lies a Holy Spring."] = "Il ne manque plus qu'un dernier réactif pour compléter l'enchantement. Au sud, vers la côte occidentale, loin au-delà des falaises, coule une source sacrée.",
    ["There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers."] = "Je n'ai plus aucun doute sur le fait qu'un puissant démoniste réside dans l'enceinte de Stromgarde. Régulièrement, en utilisant une relique de magie des arcanes, ce démoniste a invoqué un grand nombre de démons.",
    ["There's a high demand for the succulent taste of crawler meat among my customers; especially the meat from the monstrous crawlers."] = "Le goût succulent de la chair de clampant est très prisé parmi mes clients.",
    ["There's a valley to the southeast, the Valley of Bones, haunted by Magram ghosts. Sounds scary, doesn't it? Well think how scary it is to the Magram!"] = "Il y a une vallée au sud-est, la vallée des Ossements, qui est hantée par les fantômes magram. Effrayant, n'est-ce pas ? Et si ça l'est pour nous, imaginez ce que les Magram en pensent !",
    ["There, I did what Razzeric wanted. Just tell him to be careful when he sets this off. If he makes the slightest mistake, he won't be moving forward, he'll just be a burnt spot on the track."] = "Voilà ! J'ai fait selon les recommandations de Razzeric. Dites-lui simplement d'être prudent quand il installera ce truc.",
    ["These deviate creatures have strange, otherworldly properties."] = "Tandis que Naralex s'enfonçait toujours plus profondément dans son cauchemar, des bêtes étranges émergèrent de sous les Tarides, jusqu'aux Cavernes des lamentations.",
    ["They ain't a witch doctor; they spend their time castin' bones or readin' the leaves for insight - not hexin' people. As a shaman, you already know somethin' about the power of augury; we Zandalar prize the insight they give to the tribe."] = "Les augures de notre tribu sont révérés pour leur don de seconde vue. Ce ne sont pas des sorciers-docteurs qui passent leur temps à lancer des os ou à lire des feuilles pour comprendre le monde – et ils ne lancent pas de maléfices à tort et à travers, eux.",
    ["They call themselves the Undermarket: Cutthroat traders that will sell, move, trade and do just about anything for the right price. It gets worse."] = "Ils se sont donnés le nom de Sous-marché : des commerçants sans vergogne qui vendront, intimideront, commerceront, ou feront à peu près n'importe quoi contre la bonne somme d'argent. Mais les choses empirent, <name>.",
    ["They imbue their breastplates with powerful mojo. If their beliefs falter in the face of the enemy, their breastplate will not."] = "Les armes et les armures donnent du pouvoir au sein de la tribu. Les libres-penseurs sont honorés pour cela.",
    ["They want the impossible from me! The Steamwheedle Cartel wants me to teach the Southsea pirates a lesson."] = "Argh ! Mais ils veulent l'impossible !",
    ["Think you can match wits with Daryl the Bold, huh? I should think not! Of course, you're more than welcome to try. Here's a challenge that should prove to be above your abilities, so don't feel too bad if you can't face up to it."] = "Vous croyez pouvoir vous mesurer à Daryl l'Intrépide, hein ? Si j'étais vous, je n'y croirais pas ! Bien sûr, vous êtes libre d'essayer. Voilà un défi qui devrait être au-dessus de vos capacités, alors ne culpabilisez pas trop si vous n'êtes pas à la hauteur.",
    ["Thinning the younger population of creatures here in Shadowglen was a good start, but there is still work to be done. The resources of the forest will be depleted too quickly if the problem is not addressed."] = "Salutations, <name>. Je suis le Conservateur Ilthalaine.",
    ["This is bad. It seems the Daggerspines are amassing for an attack. Naga are known for their ruthlessness in battle. They will keep attacking until I am dead."] = "Ça ne se présente pas bien. Il semble que les Daguéchine se regroupent pour une attaque. Les nagas ont la réputation d'être impitoyables dans la bataille et ne cesseront d'attaquer tant que je n'aurai pas rencontré la mort. Je ne considère pas ma vie plus précieuse que celles des membres de mon équipage, mais vous devez aider à ma sauvegarde.",
    ["This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak. She'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here."] = "Ce parchemin vient de la dryade rusée nommée Rynthariel, Maître des clés de l'antre des Serres, au pic des Serres-Rocheuses. Elle ne pourra plus contacter la personne sur qui vous l'avez pris, hein ?",
    ["This will at least protect her from harm longer if she finds trouble. Return to me here after you've done your duty to Elune."] = "J'ai besoin de votre aide, <name>. Je dois rester ici pour former les autres étudiants, mais vous, vous pouvez aller porter secours à l'une de nos Sentinelles, juste au sud de Dolanaar.",
    ["This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains."] = "C'est la partie la plus délicate, car le plan comprend une difficulté. Dans les montagnes, au nord d'ici, vous trouverez un petit sentier.",
    ["This world has been victim to massive mystic struggles, which tore magic currents from once stable channels. We struggle to determine the effects these changes have caused, and some of us fear the worst!"] = "Les importantes luttes mystiques que le monde a vécues ont fait déborder les courants magiques de leurs canaux autrefois stables. Nous essayons de déterminer quels effets ces changements ont provoqué et certains d'entre nous craignent le pire !",
    ["Through my divinations, I see that an item of power hides deep within the Burning Blade Coven, guarded by beasts and black magic. It is called the Burning Blade Medallion, and your next task is to find it and remove it from the coven."] = "Mes divinations me font voir qu'un objet de puissance se trouve loin à l'intérieur du convent de la Lame ardente, et qu'il est gardé par des bêtes et de la magie noire. Vous devez trouver cet objet, le Médaillon de la Lame ardente et le prendre au convent.",
    ["Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed."] = "Thule m'a raconté qu'il y a longtemps, lui et deux de ses confrères créèrent une Baguette magique, la fusion des trois Baguettes que les mages possédaient alors.",
    ["To Whom It May Concern: If you're reading this, I'm either dead or soon to be dead. It's hard to say. Most of the crew is dead anyhow. Found information about a Titan."] = "A ceux que cela intéresse, Si vous lisez ceci, je suis mort ou je ne tarderai pas à l'être, c'est difficile à dire. Presque toute l'équipe y est déjà passée. Trouvé des informations sur un titan. De grandes batailles entre lui et un Dieu très ancien.",
    ["To get paid, you're gonna have to get back to Ironforge and speak to Roetten himself. He'll love getting Leftwitch's package out of the way anyway."] = "Pour être <payé/payée>, vous devez retourner à Ironforge et parler à Roetten en personne. Il aimera être débarrassé de la caisse de Leftwitch, de toute façon.",
    ["To have a chance against Kurzen, we need his healing support neutralized. He has gathered a large number of Medicine Men who heal his forces with Jungle Remedies and poison our fighters with Venom Fern Extracts."] = "Si nous voulons avoir la moindre chance contre Kurzen, nous devons neutraliser ses services de soins. Il a rassemblé un nombre important de Guérisseurs qui soignent ses troupes avec des remèdes tropicaux et empoisonnent les nôtres avec des extraits de fougère vénéneuse.",
    ["To pass this trial, you must travel south to the Field of Giants. There you will find a host of crawling, insect creatures. They are new to the Barrens and I do not like what they herald."] = "Pour passer l'épreuve, vous devez voyager vers le sud jusqu'au Champ des géants. Là-bas, vous trouverez un grand nombre d'insectes rampants. Ils sont récemment arrivés dans les Tarides et je pense que cela ne présage rien de bon.",
    ["To survive, I have to be tricky! I know the recipe for flash bombs."] = "Les Terres ingrates sont inhospitalières. De dangereux prédateurs et de puissants charognards y pullulent.",
    ["To tell you the truth, although there are no volcanoes here in Winterspring, I believe that there are far more threatening reasons for these hot springs..."] = "Pour vous dire la vérité, bien qu'il n'y ait pas de volcan ici au Berceau-de-l'Hiver, je pense que ces sources chaudes représentent bien plus de menaces… Enfin, je pense que vous voulez voir ça par vous-même.",
    ["To the Caverns of Time you go, Lord:Lady;. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection."] = "Rendez-vous dans les grottes du Temps, <monseigneur/dame> <name>. Anachronos attend votre retour. Donnez-lui l'œil de C'Thun.",
    ["Travel to his cottage just north of town, and execute Stalvan, once and for all. When the deed is done, travel to Madame Eva's and show her his family ring."] = "Stalvan Mistmantle est un dépravé. De nombreuses victimes ont perdu la vie entre ses mains.",
    ["Travelers keep asking me about the Stonetalon Mountains. It seems to be a popular place for adventure--it doesn't matter if you're seeking wyvern, elementals, or you have business with the Venture Co."] = "Les voyageurs m'interrogent toujours au sujet des Serres-Rocheuses. C'est une région populaire pour qui cherche l'aventure, qu'il s'agisse de traquer des wyverns, des élémentaires, ou du personnel de la KapitalRisk.",
    ["Tymor didn't give me anything to pay you with, so I suggest you take it up with him when you get back to Ironforge. I'm sure he'll still be in his place in the Mystic Ward."] = "Tymor ne m'a rien donné avec lequel je puisse vous payer, aussi je suggère que vous abordiez le sujet directement avec lui lorsque vous retournerez à Ironforge. Il est certain qu'il occupe toujours la même place dans la Garde mystique.",
    ["Ugh... It's so hot... I was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion."] = "Wouf… c'est tellement chaud… J'explorais le secteur lorsque soudain, la chaleur est devenue insupportable. Je dois souffrir d'insolation. Je vous en prie, aidez-moi à retourner à mon ami Spraggle au refuge des Marshal. Je pense que je vais encore suffisamment bien pour être capable de vous suivre jusque là-bas.",
    ["Under normal circumstances, Rigger and I would lead our kodo past the Kolkar Centaur. Every now and then we hear the Centaur war drums, and when we hear those we stop."] = "En temps normal, Rigger et moi conduirions nos kodos à travers le territoire des centaures Kolkar. Mais depuis quelque temps, nous entendons résonner les tambours de guerre des centaures.",
    ["Unfortunately, I can't dish out the beats like I used to, due to this here fat finger problem. Ye see, the climate out here combined with the lack o' air pressure makes me fingers expand."] = "Malheureusement, je ne peux plus tabasser les bêtes comme avant, à cause de mon problème de gros doigts. Vous voyez, le climat d'ici en plus de la basse pression fait se dilater mes doigts.",
    ["Unfortunately, I see the only way to stop this threat to Felwood is a frontal attack. There are no other ways into Shadow Hold, and I have no means to teleport you inside."] = "La seule solution pour arrêter la menace qui pèse sur Gangrebois est malheureusement une attaque frontale. Il n'y a pas d'autre façon d'accéder au Fort des ombres, et je n'ai pas la possibilité de vous téléporter à l'intérieur.",
    ["Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes."] = "Après des analyses approfondies de la situation, il semble que non seulement nous avons échoué à éradiquer les troggs mais que nous avons changé la majorité de la race gnome en horribles gnomes lépreux.",
    ["Using the water you brought, you will be able to temporarily douse the flame that holds the centaur relic. It will not work permanently, however, so you will have to be quick about it."] = "En l'aspergeant avec l'eau que vous avez apportée, vous pourrez temporairement éteindre la flamme qui protège la relique des centaures. L'effet sera provisoire, vous devrez faire vite.",
    ["Valdred, once my good friend, was my wife's murderer. Although I am incapable of grieving, I do yearn for revenge. If you kill Valdred and bring me his cursed hands, then I will reward you."] = "Valdred, autrefois un bon ami à moi, est le meurtrier de ma femme. Bien que je sois incapable de ressentir de la peine, j'aspire à la vengeance. Si vous tuez Valdred et me rapportez ses mains maudites, alors je vous récompenserai.",
    ["Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the amulet back together."] = "L'âme de Valthalak était conservée dans cette amulette. Aveuglés par la cupidité, nous l'avons brisée en trois, sans savoir que nous allions être maudits pour cela. Le seul moyen d'arrêter le sort lancé par Valthalak est de réunir le médaillon.",
    ["Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the medallion back together."] = "L'âme de Valthalak était conservée dans cette amulette. Aveuglés par la cupidité, nous l'avons brisée en trois, sans savoir que nous allions être maudits pour cela. Le seul moyen d'arrêter le sort lancé par Valthalak est de réunir le médaillon.",
    ["Vengeance is power. The Zandalar vindicator is such power."] = "La vengeance est une force. Les redresseurs de torts zandalar utilisent cette force.",
    ["Wanted: A skilled fighter to deal with the threat of the Pterrordax that inhabit the Un'Goro Crater. Their numbers are growing, and they are becoming a menace to travelers in the area."] = "On recherche : un guerrier compétent et talentueux pour se porter contre la menace des pterreurdactyles qui hantent le cratère d'Un'Goro. Leur nombre va croissant et ils sont en train de devenir un danger pour les voyageurs qui passent dans les environs.",
    ["Warlocks tread dangerous ground in dealing with demons, but our demoniacs take this one step further. Through an ancient and arcane ritual, they allow a demon to enter their being."] = "Lorsqu'ils négocient avec les démons, les démonistes s'aventurent sur un terrain dangereux, mais nos démoniaques poussent le processus encore plus loin. Grâce à un ancien rituel des arcanes, ils permettent à un démon d'entrer dans leurs corps.",
    ["Warning: Proceed into Sishir Canyon west of here at your own risk. Besseleth and her eight-legged children of the forest have claimed this canyon as their webbed lair."] = "Attention : si vous pénétrez dans le Canyon de Sishir, à l'ouest, vous le faites à vos risques et périls. Besseleth et ses enfants arachnéens de la forêt ont pris possession du territoire, et en ont fait leur repaire et leur nid.",
    ["We Forsaken are at war with the Lich King's army of the Scourge: necromantically raised armies of the undead, foul beasts of the north, and tormented spectres."] = "Nous, les Réprouvés, sommes en guerre contre le roi-liche et les troupes du Fléau : leurs armées de morts-vivants animés par la nécromancie, des bêtes immondes venues du nord et des spectres tourmentés.",
    ["We Zandalar invest power in those who speak with the authority of divinity."] = "Nous autres Zandalar donnons du pouvoir à ceux dont la voix résonne de l'autorité des dieux.",
    ["We Zandalar know not of druidic ways; nature is to be shaped by our need, not the other way around."] = "Nous autres Zandalar, nous ignorons les voies des druides.",
    ["We Zandalar prize what we wear as a symbol of accomplishment."] = "Chez les Zandalar, les tenues sont le symbole des succès remportés.",
    ["We are hunters. Down below in Mulgore there is a mighty kodo named Arra'chea."] = "Vous avez passé les rites de la Terre-mère et avez désormais votre place parmi nous, à Thunder Bluff. Mais pour maintenir un prestige si durement gagné, vous devez continuer à prouver votre valeur auprès de votre peuple.",
    ["We are in short supply of a few items at the Warsong lumber camp!"] = "Il nous manque quelques fournitures au Camp de bûcherons Warsong !",
    ["We cannot allow the Burning Blade a foothold in Durotar! We must destroy them before their evil festers!"] = "Nous ne pouvons permettre à la Lame ardente de prendre pied en Durotar ! Nous devons les détruire avant que ce mal ne suppure !",
    ["We have a real infestation problem to the west. Tunnel rat kobolds have moved into the foothills, setting up dens and fouling our land with their filth!"] = "Nous avons vraiment un problème de vermine à l'ouest. Les rats des tunnels kobolds sont venus dans les collines, ont creusé leurs terriers et contaminé notre terre avec leur pestilence !",
    ["We have discovered another base of operations for the Twilight's Hammer. It is called Twilight's Run; it is a cave tucked in the northeast corner of Silithus."] = "Nous avons découvert une autre base du Marteau du crépuscule. Elle s'appelle le Défilé du crépuscule ; c'est une caverne nichée dans le coin nord-est de Silithus.",
    ["We have not sat idly by for a millennium. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world."] = "Nous ne sommes pas restés inactifs pendant un millénaire, <name>. Nous avons vu ces bêtes dévorer ceux des leurs qui ne leur semblaient plus utiles. Nous les avons écoutées alors qu'elles préparaient la destruction de notre monde.",
    ["We heard the cries in the middle of the night. Then this morning, sure enough, the herd was missing two rams. That dastardly beast known as Vagash has been preying on our livelihood."] = "Nous avons entendu des cris au milieu de la nuit. Et ce matin, il manquait deux béliers dans le troupeau. C'est cette bête poltronne connue sous le nom de Vagash qui s'en est prise à notre gagne-pain.",
    ["We must find if Yenniku is dead. Slay the Bloodscalp Headhunters and take from them their Shrunken Heads. You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them."] = "Nous devons découvrir si Yenniku est mort. Tuez les Chasseurs de têtes Bloodscalp et prenez leurs Têtes réduites. Vous devez en réunir beaucoup, énormément, pour que je puisse m'assurer que celle de Yenniku n'est pas parmi elles.",
    ["We must save Sharpbeak! Fight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!"] = "Bec-tranchant doit être secouru ! Frayez-vous un chemin, à coups d'épée s'il le faut, jusqu'au sommet de Jinth'Alor, au coeur du territoire des Vilebranch et arrachez la clé de la cage à la vile prêtresse maléfique Maléficia.",
    ["We must use restraint against Eranikus. We are to redeem him not destroy him. Tyrande is already en route to assist us in this task. We must weather the dragon's blows and save Nighthaven from certain destruction."] = "Il faudra faire preuve de maîtrise avec Eranikus. Nous sommes là pour veiller à sa rédemption, pas à sa destruction. Tyrande est déjà en route pour nous aider dans cette tâche. Nous devons encaisser les coups du dragon et sauver Havrenuit d'une destruction certaine.",
    ["We need to get out of here. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell."] = "Nous devons sortir d'ici, <name>. Aidez-moi à récupérer mon équipement dans la zone d'approvisionnement et à libérer mes amis. Si nous nous en sortons, vous devrez vous rendre à la Veille de Morgan et parler au maréchal Maxwell.",
    ["We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions."] = "Nous maîtriserons le problème des worgens, n'ayez aucune crainte là-dessus. Ce mal que votre amie a introduit dans nos bois sera contenu et je ne lui en veux pas pour ses actions.",
    ["We were deep in a vast mine in Westfall, hidden beneath a barn in Moonbrook. No clue where these stinkin' thieving types came from. Anyway, the mine tunnel collapsed on us."] = "Nous étions au plus profond d'une mine dans la marche de l'Ouest, cachés derrière un baraquement à Ruisselune. Impossible de savoir d'où viennent ces voleurs puants... Bref, la mine s'est effondrée sur nous.",
    ["We're sitting on a goldmine here, I tell you - a goldmine! Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them."] = "Nous sommes assis sur une mine d'or ici, je vous le dis ! Une mine d'or ! Les os de kodos changeront la face du monde pour toujours… J'ai des clients qui en font des meubles, des instruments de musique, et même des poudres explosives.",
    ["We've learned that a source of furbolg corruption is from the satyr. They hold sway via talismans that they channel magic through. If the furbolg have a chance at salvation, we must lure out the satyr corruptor and take that talisman!"] = "Les satyres sont une des sources de la corruption des furbolgs. Leur joug est assuré par des talismans qui leur servent à canaliser de la magie. Pour sauver les furbolgs, nous devons arracher son talisman au satyre corrupteur !",
    ["Well met. I've something that might interest you. I have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality."] = "Voilà une heureuse rencontre, <class>, car j'ai quelque chose qui pourrait vous intéresser. J'ai en ma possession un ensemble d'armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d'une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d'une pièce d'armure plus ordinaire… et d'une petite faveur.",
    ["Well, the only caravan brave enough to travel these parts relies on me. Ever since I learned how to rejuvenate and control aged and dying kodos with my kodo kombobulator, the caravan owner Cork, Rigger, and I entered a partnership."] = "Bibbly pense être le seul gobelin de Désolace à savoir comment faire de l'argent. Peuh… Moi, je suis responsable de la seule caravane suffisamment courageuse pour voyager dans ces contrées.",
    ["Wha.. What happened? The last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs."] = "<Kernobee grogne>Qu… Que s'est-il passé ? La dernière chose dont je me souviens est d'avoir été capturé par un groupe de nains Sombrefer, d'avoir été battu comme plâtre et jeté ici avec ces troggs crasseux. Sortez-moi de là, <name> !",
    ["What?! Ah, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it? You did the work, so I suppose it is only right you reap the greatest reward from it."] = "Comment ? Ah, j'ai parlé d'une récompense, n'est-ce pas ? Bon... ça m'apprendra à ouvrir la bouche !",
    ["When I struggled with the Forsaken's poisons, I had a vision. I had a vision of the druids in the Dor'danil Barrow Den, poisoned... murdered by the undead!"] = "Lorsque je me battais avec les poisons des Réprouvés, j'ai eu une vision. J'ai vu les druides du Refuge des saisons de Dor'danil empoisonnés... Assassinés par les morts-vivants !",
    ["When doing this though, be sure to save me the water elemental cores!"] = "Si je dois rester ici à gérer cette boutique en pleine Côte oubliée, j'aurais besoin que l'on s'occupe de ces fichus élémentaires.",
    ["When my life was ended upon the rocks, I had no clue what the afterlife held for me. The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off."] = "Quand ma vie a pris fin sur ces rochers, je ne savais pas que je pouvais espérer quelque chose après la mort. Cette nuit-là, le phare était éteint parce que le Vieux Troubloeil avait fait fuir la famille qui s'en occupait.",
    ["When we fled Gnomeregan, we left so much data behind! Vitally important data! I need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan."] = "Quand nous avons fui Gnomeregan, nous avons dû abandonner tant de données importantes ! J'ai besoin des données de la carte perforée prismatique d'une Matrice d'encodage 3005-D, dans Gnomeregan. C'est votre destination ; mais pour cela, vous devez d'abord accéder aux terminaux de modèles -A, -B et -C.",
    ["While I do possess much knowledge about the owlbeasts you defeated in Winterspring, I am not very learned on the subject of the magics they wield."] = "J'ai beau posséder de solides connaissances sur les Chouettards que vous avez vaincus au Berceau-de-l'Hiver, je ne sais pas grand-chose de la magie qu'ils utilisent.",
    ["While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have! As you see, my observatory is ready to go, but it needs the smaller of the two lenses."] = "J'aimerais récupérer toutes mes marchandises. Hélas, je suis sûr que ce n'est pas possible. Mais il y a des choses que je dois absolument récupérer !",
    ["While the majority of the books were filled with - to put it bluntly - tripe, there were some gems. One of those tomes documented the creation of a set of armor fit for an archmage: Frostfire."] = "Ma fonction de gardienne m'a permis d'avoir accès à de nombreux effets personnels de Medivh. Ce sont ses livres qui m'ont appris le plus.",
    ["While we still know very little about why the furbolg have been ingesting this strange substance, I do think it's best that we put a stop to it before it gets out of hand."] = "Bien que nous ne sachions pas vraiment pourquoi les furbolgs ont ingéré cette étrange substance, je pense qu'il vaudrait mieux y mettre un terme avant que ça ne dégénère.",
    ["While you have been exploring Un'Goro, I have seen other things that a mighty hunter such as yourself would relish in. One such sight was a huge ape among the other gorillas to the north."] = "Pendant que vous exploriez Un'Goro, j'ai vu certaines choses <qu'un maître/qu'une maîtresse> de la chasse apprécierait grandement. J'ai vu un singe immense parmi les autres gorilles, au nord.",
    ["While you were down there I happened to notice that one of those beasts stood out from the rest. He was bigger and more menacing. I bet he's the one who led the others here to cause the disruption to the dig site."] = "Lorsque vous étiez là-bas, j'ai remarqué qu'un de ces monstres se tenait à l'écart des autres. Il était plus grand et plus menaçant. Je parie que c'est lui qui a incité les autres à venir ici interrompre les fouilles.",
    ["While you were gathering the supplies, I had some of my people handle marking the Scourge buildings we need demolished. Here's the plan: I'm going to give you ten sticks of my special compound."] = "Pendant que vous collectiez les provisions, quelques-uns de mes agents ont pu marquer les bâtiments du Fléau que nous devons démolir. Voici le plan : je m'en vais vous donner dix bâtons de mon mélange spécial.",
    ["While you were gone I fixed the pot you brought me. I even added an extra steam whistle, and look! There's a new chopper at the bottom that'll cut through leg bones!"] = "Pendant que vous étiez <parti/partie> j'ai réparé la cocotte que vous m'aviez apportée. J'y ai même ajouté un autre sifflet à vapeur, et regardez : il y a un hachoir au fond pour réduire les os de pattes en bouillie ! Oui !",
    ["While you were out gathering, I uncovered some old text in one of my tomes that indicates that an ancient plague wiped out thousands of innocent victims."] = "Dame Sylvanas a fait appel à la Société royale des apothicaires.",
    ["Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home."] = "Voyez ce vieux fou de Mok'Morokk, qui se complaît dans son pouvoir et Tharg, qui combat les démons du désespoir et de la vengeance tout en espérant prendre la direction du clan.",
    ["Why don't we go over to the forge and get started on this? I've been preparing for your arrival for some time, so it shouldn't take long at all."] = "Pourquoi n'irions-nous pas à la forge pour commencer ? J'ai préparé votre arrivée depuis quelque temps déjà et tout devrait être prêt.",
    ["Will you assist me, mortal? Will you find the prayer to Elune? As I stated, the prayer was etched onto a golden tablet. One of these idol worshipping scoundrels must have it on their person."] = "Me viendrez-vous en aide, <mortel/mortelle> ? Écoutez mon récit.",
    ["With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache. Perhaps he or someone there can make further sense of what the gnolls are up to."] = "Une fois trouvés les plans des gnolls, il reste à les porter à Hadoken Swiftstrider au Camp Mojache. Peut-être comprendra-t-il les projets des gnolls…",
    ["With the loss of Guard Captain Malkhor, the position of Guard Captain of Revantusk is once again open."] = "Suite à la mort du capitaine Malkhor, le poste de capitaine de la garde de Revantusk est à pourvoir.",
    ["Without the blessings of Alexstrasza the Life-Binder and Nozdormu the Timeless, Teldrassil's growth has not been without flaw."] = "Sans la bénédiction d'Alexstrasza la Lieuse de vie et celle de Nozdormu l'Éternel, la croissance de Teldrassil ne fut pas parfaite.",
    ["Wouldn't ye know it, every time ol' Hansel wants to take a moment to relax and reflect upon his life, the powers that be give him another job."] = "J'vous dis pas, chaque fois que le vieil Hansel veut se reposer un moment et réfléchir au sens de la vie, les puissances supérieures lui donnent un nouveau travail.",
    ["Wreak havoc on the minions of evil. Zul'Gurub must taste Zandalar vengeance."] = "L'ultime vengeance attend à l'intérieur de Zul'Gurub. Hakkar ne doit pas revenir.",
    ["Yes, imbecile, perhaps you are ready for a more involved set of missions. The albino demon bat, Duskwing, roams the countryside just north of here."] = "Vous avez, pour l'instant, réussi toutes les missions que je vous ai confiées ; même si vous ne l'avez pas fait de la manière la plus opportune qui soit. Je suppose que vous vous sentez en mesure d'affronter de nouveaux défis.",
    ["Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."] = "En effet, je connais l'enchantement dont vous avez besoin, <class>. Mais je ne suis pas de ceux qui distribuent des faveurs gratuitement, même si vous m'avez été <envoyé/envoyée> par un vieil ami.",
    ["Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold! Those bastards must be dealt with. Their paranoia has them in a state of frenzy."] = "J'ai encore perdu un navire contre ces humains trop zélés du Fort du Nord ! Nous devons nous occuper de ces bâtards. Leur paranoïa les met dans un état de totale frénésie.",
    ["You are one of my lieutenants! Prepare yourself. I will call upon you soon. My time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer."] = "Hmm, des chefs de la Lame brûlante... cela m'inquiète beaucoup. S'ils sont utiles à Neeru, alors ce sont eux qu'il faut viser en premier. Ce satyre...",
    ["You be ready for your first test. South of Razor Hill, just outta town, one of our grunts be hurt fightin' off some o' Proudmoore's old troops."] = "V'là votre premier test, <name>. Au sud de Tranchecolline, juste à l'extérieur de la ville, un d'nos fantassins a été blessé en s'battant contre les troupes de Proudmoore.",
    ["You dare challenge Overlord Mok'Morokk? Haw! Me crush tiny! You tell me when ready for good beating."] = "Toi oser défier le Seigneur Mok'Morokk ? Morbleu ! Moi écraser <race> comme un insecte ! Toi me dire quand vouloir bonne raclée.",
    ["You did so well with the lieutenants and underlings that I'd like you to do one last thing for me. Serena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago."] = "Vous vous en êtes tellement bien <sorti/sortie> avec les lieutenants et autres harpies subalternes que j'aimerais que vous fassiez une dernière chose pour moi. Serena Plumesang est la sœur d'une harpie nommée Plumesang qui a été tuée par Rexxar il y a longtemps.",
    ["You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?"] = "Vous vous imaginez être <un héros/une héroïne> de l'Aube, pas vrai ? J'ai vu nos plus grands soldats submergés par la racaille de Kel'Thuzad ! Après ça, combien pensez-vous que je vais parier sur <un ahuri fraîchement débarqué/une ahurie fraîchement débarquée> ?",
    ["You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs."] = "Vous trouvez une sacoche sous le corps du tauren. Il la tient encore serrée entre ses bras comme s'il essayait de la protéger pendant l'attaque des troggs.",
    ["You got here just in the nick of time! The Pyrewood Council will be returning any moment. Arugal has other matters to tend to in the keep. He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control."] = "Vous avez fait vite, <name> ! Les Conseillers de Bois-du-Bûcher vont revenir dans un instant. Arugal utilise les membres du Conseil comme autant de marionnettes pour garder la main mise sur le village. Mais je pense que sans le Conseil, les partisans d'Arugal se retourneraient contre leur maître.",
    ["You have a promising air about you, and will prove yourself to the tribe. Perhaps someday soon you will be welcomed into the great city of Thunder Bluff."] = "Vous avez un air prometteur, et vous allez avoir l'occasion de prouver votre valeur au sein de la tribu. Peut-être le jour est-il proche où l'on vous accueillera dans la grande ville de Thunder Bluff.",
    ["You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect. Go now back to your trainer, Mathrengyl Bearwalker, in Darnassus."] = "Vous avez terminé les leçons nécessaires, enseignées à tous les jeunes druides avant qu'ils ne puissent adopter un aspect aquatique. Retournez voir votre Maître, Turak Runetotem, à Thunder Bluff.",
    ["You have done well. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles."] = "Vous avez bien œuvré, <name>. Vous avez réussi mon test, et les tests d'avant. Retournez voir Dom aux Mille pointes.",
    ["You have proven your loyalty to King Magni. And your hatred for the Dark Iron scum is as great as my own. There is a task I wish to complete myself but I am bound by honor to stay with Longbraid."] = "Vous avez prouvé votre loyauté au roi Magni, <class>. Et votre haine de la vermine Sombrefer est aussi forte que la mienne. Voici une tâche que je pourrais effectuer mais je suis obligé par une dette d'honneur de rester à Longbraid.",
    ["You have proven yourself time and again, and your resourcefulness seems to rival even that of Kurzen himself. You may be the salvation of our band of rebels...if you can pit yourself against Kurzen and prevail!"] = "Vous avez montré votre valeur à maintes reprises, et vos ressources semblent même concurrencer celles de ce Kurzen en personne. Il se peut que vous représentiez le salut pour notre bande de rebelles… si vous pouvez vous mesurer à Kurzen et le vaincre !",
    ["You have the look of a fisherman! I love to fish - been fishing all my life. The best bait to use is soft-shelled clam meat; the fish just can't resist, you know what I mean?"] = "Vous avez tout l'air d'un pêcheur, <class> ! J'adore pêcher, et j'ai pratiqué cette activité pendant toute ma vie. Le meilleur appât qui existe est sans aucun doute la chair de praire ; les poissons n'y résistent pas, si vous voyez ce que je veux dire.",
    ["You have uncovered a dark threat to the land. The Resonite cask you have found in that cave houses a slumbering Earthen by the name of Goggeroc."] = "Vous avez découvert une sombre menace pour cette terre, <class>. La gangue de résonite que vous avez trouvée dans cette caverne abrite un Terrestre dormant du nom de Goggeroc.",
    ["You look as though you might need something to keep your hands warm, hm? I'll tell you what would help: a pair of nice, warm gloves."] = "Qu'est-ce que c'est ? On dirait que vous avez besoin de quelque chose pour tenir chaud aux mains, non ?",
    ["You look like a capable. Perhaps you're looking to make some money? Cork and I started this caravan to make a bundle of money; little did we know the dangers of turning a buck!"] = "Vous semblez compétent, <race>. Peut-être voudriez-vous gagner un peu d'argent ? Cork et moi avons monté cette caravane pour faire fortune, mais nous ignorions les dangers que recélait cette entreprise !",
    ["You looking fer work? I might have some if you're up for a little challenge. I got a friend named Groy who makes a killing selling what the naga call akiris reed: it's some kind of valuable ocean reed."] = "Vous cherchez du boulot, <name> ? J'en ai p'têt' si vous vous sentez <prêt/prête> à relever un p'tit défi. J'ai un ami, nommé Groy, qui fait un malheur en vendant c'que les nagas appellent des roseaux akiris : c't'un genre de roseau marin qu'a d'la valeur.",
    ["You may have killed the raptors, but the silver they stole must be recovered! I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds."] = "Vous avez peut-être tué les raptors, mais l'argent qu'ils ont volé doit être récupéré ! Des rapports indiquent que les raptors ont un important site de nidification au sud de Ratchet.",
    ["You must defeat Myzrael before she grows in strength. If you do not, then once she has gathered enough power she will challenge her captors!"] = "Vous devez battre Myzrael avant que sa force n'augmente. Sinon, une fois qu'elle aura rassemblé suffisamment de pouvoir, elle défiera ses ravisseurs !",
    ["You must master both to have any chance of success in Zul'Gurub... and any chance of being like the Zandalar predators."] = "Un prédateur sait traquer ses proies, mais un prédateur avisé sait aussi comment les frapper alors même qu'elles sont rassemblées. Vous devez maîtriser ces deux arts si vous voulez réussir à Zul'Gurub… et si vous voulez ressembler aux prédateurs des Zandalar.",
    ["You pick up the sack carefully and prepare to make your way back to Jessir Moonbow on the border of Felwood and Ashenvale. Hopefully the paladin will be given the proper respects once you've passed his remains on to his friends."] = "Vous ramassez le sac avec précaution et vous vous apprêtez à reprendre votre chemin pour rejoindre Jessir Moonbow, à la frontière de Gangrebois et Ashenvale. Heureusement, le paladin recevra les honneurs qui lui sont dus une fois que vous aurez confié ses restes à ses amis.",
    ["You secure the sealed testing kit for the journey back to the Undercity. Apothecary Zinge waits for you and the sealed field testing kit there."] = "\"Et voilà, la source d'énergie est enlevée et les données sont préservées. Bien, faites attention sur la route et tout ça.",
    ["You seek to prove your worth to my kind, mortal? Very well, perhaps we can be of mutual assistance. The ancient sandworm, Ouro, is a being of legendary power."] = "Vous souhaitez prouver votre valeur aux yeux de mon espèce, <mortel/mortelle> ? Très bien, peut-être pouvons-nous nous aider mutuellement. Il existe un très ancien ver des sables d'une puissance légendaire, nommé Ouro.",
    ["You serve my husband well, but he does not know why Hammerfall is under attack."] = "Vous avez bien servi mon mari, <class>, mais il ne connaît pas la véritable cause des attaques contre le Trépas-d'Orgrim.",
    ["You take this, mon. You take this to Aerie Peak, dead center of town by the well. You plant it! Drive it right into the ground! Show those dwarves that troll mean business!"] = "<Otho vous tend une longue lance tachée de sang, ornée de plusieurs plumes de gryphon.> Vous prenez ça, mon pote. Vous l'amenez au Nid-de-l'Aigle, pile au centre de la ville, près du puits. Et là, vous le plantez ! En plein dans le sol ! Faut montrer à ces nains que les trolls ne plaisantent pas !",
    ["You there! If you're looking for something to make yourself useful, then listen up! We need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment."] = "Vous, là ! Si vous cherchez à vous rendre utile, écoutez bien ! Nous avons besoin de recrues fraîchement déterrées pour se rendre au Glas et rechercher tout équipement utile.",
    ["You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas."] = "Vous trouverez les restes de l'équipement de nos héros tombés au combat sur les cadavres des seigneurs de Naxxramas.",
    ["You'd think that being chief digger for Marshal Expeditions means I like digging. There might be worse things to do in this world... but none really leap to mind."] = "On pourrait penser qu'être chef terrassier pour les Expéditions Marshal signifie que j'aime creuser. Il y a des choses bien plus désagréable à faire en ce monde… mais aucune ne me vient à l'esprit. Nous étions supposés creuser dans les Coteaux de la terreur - quel nom FANTASTIQUE, soit dit en passant - à la recherche de stégodons et de dimeurtrodons morts !",
    ["You'll be happy to know we appear to be making progress in the mine, thanks in no small part to your efforts. We can now turn our eyes to other concerns."] = "Il vous plaira d'entendre que nous progressons dans la mine, et cela grâce à vous. Nous pouvons maintenant nous atteler à d'autres tâches.",
    ["You'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine."] = "À présent que mes vendanges sont sauvées, apportez ce Manifeste des vendanges à Frère Neals. Il s'occupe du magasin de nourriture et de boisson de Northshire, et il est certain qu'il sera ravi d'apprendre que nous avons du raisin frais.",
    ["You've almost proven yourself to be a master hunter of panthers."] = "Vous avez presque atteint le niveau de maître-chasseur de panthères.",
    ["You've done doubly well in addressing the threat that the Zukk'ash insects pose to Camp Mojache. The threat these things pose is far from over, and I'd like to ask you for one last task on behalf of the Horde."] = "Vous avez doublement bien fait de vous occuper de la menace que les insectes Zukk'ash représentent pour le Camp Mojache. Cette menace est loin d'avoir disparu, et j'aimerais vous demander une dernière tâche pour la Horde.",
    ["You've proven to be a very reliable individual. As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance."] = "Vous avez fait la preuve de votre fiabilité, <name>. Je suis sûr que vous m'aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.",
    ["You've shown your potential to the Forsaken under normal circumstances - now let's see you under pressure. The Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far."] = "Vous avez montré vos capacités aux Réprouvés, dans des conditions normales, <name>. À présent, voyons ce que vous pouvez faire lorsque vous êtes sous pression.",
    ["Your beliefs are alien to us, heathen. Ancient Zandalar were once branded as heretics."] = "Vos croyances nous sont étrangères, <païen/païenne>. Autrefois, des Zandalar furent qualifiés d'hérétiques, au temps de la puissance de l'empire Gurubashi.",
    ["Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young. The Wildmane Totem is made, and your last task lies ahead."] = "Votre purification des puits Winterhoof et Thunderhorn est objet de discussion et de fierté parmi les esprits, jeune <name>. Le totem de Wildmane est construit et le devoir vous appelle, encore une fois.",
    ["Your previous investigations are proof that the Echo Ridge Mine needs purging. Return to the mine and help clear it of kobolds. Waste no time."] = "Vos dernières investigations ont prouvé que la mine de la Crête aux échos devait être nettoyée. Retournez-y et chassez les kobolds. Ne perdez pas de temps, <name>.",
    ["Zanzil the Outcast dwells with his followers in the Jubuwal and Aboraz Ruins, northeast of Booty Bay. He is exiled from his tribe. Why? Well..."] = "Zanzil le Paria demeure avec ses partisans dans les Ruines de Jubuwai et dans celles d'Aboraz, au nord-est de Baie-du-Butin. Il a été banni de sa tribu. Pourquoi ? Eh bien !… Zanzil a le pouvoir de soumettre la volonté des autres, et ses chefs ont peur de lui.",
    ["another tribe of Furbolgs, the Foulweald, live southeast of Astranaar. They are not as many as the Thistlefur, but their ferocity poses a future threat."] = "<name>, une autre tribu de furbolgs, les Vile-sylve, vit au sud-est d'Astranaar. Ils sont moins nombreux que les Crins-de-Chardon, mais leur férocité représente une menace latente.",
    ["ath, is it? I can tell you're bursting with pride over completing the first test, hm? As I told you before, it's no large feat. You should try your hand at boar hunting."] = "<name>af, c'est ça ? Je vois que vous exultez pour avoir réussi le premier test, pas vrai ? Comme je vous l'ai dit, ce n'était pas grand-chose. Vous devriez vous essayer à la chasse au sanglier.",
    ["it is now time for you to travel to far-off lands. You are ready. You now hunt Frostmaw, a yeti in the Alterac Mountains. He is elusive, his white coat blending into the snows of his mountain home."] = "<name>, il est temps pour vous de voyager vers de lointaines contrées. Le moment est venu. Vous devez partir à la poursuite de Gueule-glacée, un yéti des montagnes d'Alterac. Il est très difficile à trouver, car sa fourrure blanche se confond avec la neige de ses montagnes maternelles.",
    ["my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him. I want to ask a favor of you while I finish tanning these leather straps."] = "<name>, mon frère doit bientôt se présenter devant le chef Bloodhoof et il est de mon devoir de lui faire une coiffe digne de ce nom. Je voudrais vous demander une faveur, pendant que je finis de tanner ces lanières de cuir.",
    ["our scouts have identified the leader of this recent Trogg incursion. It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug."] = "<name>, nos éclaireurs ont identifié le chef des troggs qui a mené la récente incursion que nous avons subie. Il semble que ces bêtes du Loch Modan répondent aux ordres d'un certain Grawmug.",
    ["please, can you help me? My son Kron went hunting days ago, and he still hasn't returned. He went west towards the Barrens to hunt crocolisks along Southfury River."] = "<name>, pouvez-vous m'aider ? Mon fils, Kron, est parti chasser il y a quelques jours et il n'est toujours pas revenu. Il est allé à l'ouest, vers les Tarides, pour traquer des crocilisques, le long du fleuve Furie-du-Sud.",
    ["the creation of each weapon will take some time. Additionally, you may only use the power of the Felcurse once per three minutes. Its weakening properties against Razelikh the Defiler and his minions may be variable in duration."] = "<name>, la création de chaque arme va prendre un peu de temps. De plus, vous ne pourrez utiliser le pouvoir du sort Corruption qu'une fois toutes les trois minutes. Ses propriétés d'affaiblissement contre Razelikh le Souilleur et ses sbires peuvent varier dans la durée.",
    ["the gnolls are still out there. I can hear their baying as they hunt in the hills above Lakeshire. And one cry is louder than the rest - Yowler, their leader."] = "<name>, les gnolls sont toujours là. Je peux entendre leurs hurlements quand ils chassent dans les collines de Lakeshire. Et l'un d'eux hurle plus fort que les autres : Couineur, leur chef.",
    ["you are a hunter worthy of our company. From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated."] = "<name>, vos talents à la chasse sont dignes de notre compagnie. Des champs de bataille de Lordaeron aux jungles les plus denses, j'ai rarement été témoin de prouesses telles que les vôtres.",
    ["you are a with proven interest in the security of Northshire. You are now tasked with the protection of the surrounding Elwynn Forest."] = "<name>, vous êtes un <class> indubitablement impliqué dans la sûreté de Northshire. Vous avez maintenant en charge la protection de la zone entourant la forêt d'Elwynn.",
    ["you have served us well in the past, so I now entrust to you an important mission. The Grimtotem Clan is up to something secretive. Three agents of unknown origin were seen visiting the Grimtotem over the recent weeks."] = "<name>, vous nous avez bien servi par le passé, je peux donc vous confier une importante mission. Le Clan du Totem sinistre prépare quelque chose en secret. Trois agents d'origine inconnue ont été vus chez eux ces dernières semaines.",
    ["you helped us against the Magram. Now, help us beat the Maraudine! Kill the head of their clan, Khan Hratha! To face him, blow the Maraudine War Horn."] = "Vous nous avez aidés contre les Magram, <name>. À présent, aidez-nous à battre le clan des Maraudine ! Tuez leur chef, le khan Hratha ! Pour le combattre, soufflez dans la corne de guerre maraudine.",
    ["your help has been immeasurable. The time will come, no doubt, when I'll ask for your assistance against the silithid once more."] = "<name>, votre contribution a été incommensurable. Le jour viendra où je ferai de nouveau appel à vous pour lutter contre les silithides.",
    ["your services to the Warlords surpassed all we could expect from the denizens of this world. We do not understand your people's notions of gratitude, or rewarding good works, but in this case..."] = "<name>, les services que vous avez rendus aux Seigneurs de la guerre surpassent tout ce que nous attendions des habitants de ce monde. Nous ne comprenons pas la notion de gratitude, ou de récompense pour des bonnes actions, mais dans ce cas… une prime semble être à l'ordre du jour.",
}) do text[k] = v end

local objectives = GQ.LocaleObjectives
for k, v in pairs({
    ["According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.Should Korrak make himself known, destroy him and return to Warmaster Laggrond."] = "Korrak le Ragesang se cache dans les profondeurs des cavernes Winterax. D'après la légende, le chef des puissants trolls Winterax ne se montre qu'après la mort de 500 de ses guerriers.  Rendez-vous aux cavernes Winterax et massacrez tout ce qui vous fait obstacle jusqu'à ce que Korrak se montre. Tuez-le et présentez-vous au Maître de guerre Laggrond.",
    ["Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Lightforge Bracers to Deliana in Ironforge."] = "Procurez-vous 15 Echantillons de sang du Berceau-de-l'hiver et 20 pièces d'or, et apportez-les avec une paire de Brassards de Sancteforge à Deliana à Ironforge.",
    ["Acquire 6 Bloodfeather Belts and bring them to Sentinel Arynia Cloudsbreak in the Oracle Glade."] = "Acquérir 6 Ceintures plumesang et les apporter à la Sentinelle Arynia Cloudsbreak à la clairière de l'Oracle.",
    ["Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him."] = "Anachronos, aux Grottes du temps en Tanaris, veut que vous emportiez Atiesh, le grand bâton du Gardien, à Stratholme et que vous le placiez sur la Terre consacrée. Abattez l'entité qui sera extraite du bâton et retournez le voir.",
    ["Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager."] = "Andi Lynn de Gadgetzan veut que vous détruisiez la Base des Cognedunes en tuant 10 Brutes Cognedunes, 10 Massacreurs Cognedunes, et Gor'marok le Ravageur.",
    ["Apothecary Johaan in the town of Brill wants you to collect 5 Vials of Darkhound Blood."] = "Collecter 5 fioles de Sang de sombredogues pour l'Apothicaire Johaan de la ville de Brill.",
    ["Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom."] = "L'Apothicaire Zamah à Thunder Bluff veut que vous récoltiez 10 Fleurs de serpent.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Bindings if you bring her the following: 1 Desecrated Bindings, 6 Wartorn Cloth Scraps, 1 Arcane Crystal and 1 Nexus Crystal."] = "L'archimage Angela Dosantos, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'Est, vous fabriquera des manchettes de givrefeu si vous lui apportez les ingrédients suivants : 1 paire de Manchettes désacralisées, 6 Débris d'armure en tissu, 1 Cristal arcanique et 1 Cristal de nexus.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Gloves if you bring her the following: 1 Desecrated Gloves, 8 Wartorn Cloth Scraps and 4 Mooncloth."] = "L'archimage Angela Dosantos, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'Est, vous fabriquera des gants de givrefeu si vous lui apportez les ingrédients suivants : 1 paire de Gants désacralisés, 8 Débris d'armure en tissu et 4 Etoffes lunaires.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Leggings if you bring her the following: 1 Desecrated Leggings, 20 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals."] = "L'archimage Angela Dosantos, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'Est, vous fabriquera des jambières de givrefeu si vous lui apportez les ingrédients suivants : 1 paire de Jambières désacralisées, 20 Débris d'armure en tissu, 4 Etoffes lunaires et 2 Cristaux de nexus.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Sandals if you bring her the following: 1 Desecrated Sandals, 12 Wartorn Cloth Scraps, 2 Mooncloth and 3 Cured Rugged Hides."] = "L'archimage Angela Dosantos, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'Est, vous fabriquera des sandales de givrefeu si vous lui apportez les ingrédients suivants : 1 paire de Sandales désacralisées, 12 Débris d'armure en tissu, 2 Etoffes lunaires et 3 Peaux robustes traitées.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Shoulderpads if you bring her the following: 1 Desecrated Shoulderpads, 12 Wartorn Cloth Scraps, 2 Mooncloth and 3 Cured Rugged Hides."] = "L'archimage Angela Dosantos, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'Est, vous fabriquera des protège-épaules de givrefeu si vous lui apportez les ingrédients suivants : 1 paire de Protège-épaules désacralisés, 12 Débris d'armure en tissu, 2 Etoffes lunaires et 3 Peaux robustes traitées.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make a Frostfire Belt if you bring her the following: 1 Desecrated Belt, 8 Wartorn Cloth Scraps, 2 Arcane Crystals and 2 Mooncloth."] = "L'archimage Angela Dosantos, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'Est, vous fabriquera une ceinture de givrefeu si vous lui apportez les ingrédients suivants : 1 Ceinture désacralisée, 8 Débris d'armure en tissu, 2 Cristaux des arcanes et 2 Etoffes lunaires.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make a Frostfire Circlet if you bring her the following: 1 Desecrated Circlet, 15 Wartorn Cloth Scraps, 3 Mooncloth and 3 Nexus Crystals."] = "L'archimage Angela Dosantos, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'Est, vous fabriquera un diadème de givrefeu si vous lui apportez les ingrédients suivants : 1 Diadème désacralisé, 15 Débris d'armure en tissu, 3 Etoffes lunaires et 3 Cristaux de nexus.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make a Frostfire Robe if you bring her the following: 1 Desecrated Robe, 25 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals."] = "L'archimage Angela Dosantos, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'Est, vous fabriquera une robe de givrefeu si vous lui apportez les ingrédients suivants : 1 Robe désacralisée, 25 Débris d'armure en tissu, 4 Etoffes lunaires et 2 Cristaux de nexus.",
    ["Balir Frosthammer wants you to kill 6 Rockjaw Troggs and 6 Burly Rockjaw Troggs."] = "Balir Frosthammer veut que vous tuiez 6 Troggs Mâcheroc et 6 Troggs Mâcheroc forcenés.",
    ["Banish 6 Portals at Mannoroc Coven and return to Taiga Wisemane at Shadowprey Village."] = "Bannir 6 Portails, dans le convent de Mannoroc, puis retourner voir Taiga Wisemane, à Proie-de-l'Ombre.",
    ["Barkeep Daniels of Lakeshire needs a keg of Thunderbrew Lager, a cask of Merlot, a bottle of Moonshine and a skin of Sweet Rum."] = "Le tavernier Daniels de Lakeshire a besoin d'un Tonneau de Thunderbrew, d'un Tonneau de merlot, d'une Bouteille de tord-boyaux et d'une Outre de rhum doux.",
    ["Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Darnassus is the next step the tauren druid sought. Seek one of the druids there for assistance."] = "D'après la magie contenue dans la Branche de chêne à glyphes, le druide tauren voulait qu'elle soit apportée au Cercle cénarien, à Darnassus. Aller solliciter l'assistance de l'un des druides, là-bas.",
    ["Bring 1 Qiraji Ceremonial Ring, 2 Amber Idols, 5 Gold Scarabs and 5 Clay Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Anneau de cérémonie qiraji, 2 Idoles d'ambre, 5 Scarabées d'or et 5 Scarabées d'argile à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Ceremonial Ring, 2 Jasper Idols, 5 Stone Scarabs and 5 Crystal Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Anneau de cérémonie qiraji, 2 Idoles de jaspe, 5 Scarabées de pierre et 5 Scarabées de cristal à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Ceremonial Ring, 2 Obsidian Idols, 5 Silver Scarabs and 5 Bone Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Anneau de cérémonie qiraji, 2 Idoles d'obsidienne, 5 Scarabées d'argent et 5 Scarabées d'os à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Ceremonial Ring, 2 Onyx Idols, 5 Stone Scarabs and 5 Crystal Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Anneau de cérémonie qiraji, 2 Idoles d'onyx, 5 Scarabées de pierre et 5 Scarabées de cristal à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Magisterial Ring, 2 Alabaster Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Anneau de magistrat qiraji, 2 Idoles d'albâtre, 5 Scarabées en bronze et 5 Scarabées d'ivoire à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Magisterial Ring, 2 Azure Idols, 5 Gold Scarabs and 5 Clay Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Anneau de magistrat qiraji, 2 Idoles azur, 5 Scarabées d'or et 5 Scarabées d'argile à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Magisterial Ring, 2 Lambent Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Anneau de magistrat qiraji, 2 Idoles brillantes, 5 Scarabées en bronze et 5 Scarabées d'ivoire à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Magisterial Ring, 2 Vermillion Idols, 5 Silver Scarabs and 5 Bone Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Anneau de magistrat qiraji, 2 Idoles vermillon, 5 Scarabées d'argent et 5 Scarabées d'os à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Martial Drape, 2 Alabaster Idols, 5 Stone Scarabs and 5 Crystal Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Drapé martial qiraji, 2 Idoles d'albâtre, 5 Scarabées de pierre et 5 Scarabées de cristal à Keyl Swiftclaw, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Martial Drape, 2 Azure Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Drapé martial qiraji, 2 Idoles azur, 5 Scarabées en bronze et 5 Scarabées d'ivoire à Keyl Swiftclaw, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Martial Drape, 2 Jasper Idols, 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Drapé martial qiraji, 2 Idoles de jaspe, 5 Scarabées d'or et 5 Scarabées d'argile à Keyl Swiftclaw, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Martial Drape, 2 Onyx Idols, 5 Silver Scarabs and 5 Bone Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Drapé martial qiraji, 2 Idoles d'onyx, 5 Scarabées d'argent et 5 Scarabées d'os à Keyl Swiftclaw, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Ornate Hilt, 2 Jasper Idols, 5 Crystal Scarabs and 5 Stone Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Manche orné qiraji, 2 Idoles de jaspe, 5 Scarabées de cristal et 5 Scarabées de pierre au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Ornate Hilt, 2 Obsidian Idols, 5 Silver Scarabs and 5 Bone Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Manche orné qiraji, 2 Idoles d'obsidienne, 5 Scarabées d'argent et 5 Scarabées d'os au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Regal Drape, 2 Lambent Idols, 5 Stone Scarabs and 5 Crystal Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Drapé royal qiraji, 2 Idoles brillantes, 5 Scarabées de pierre et 5 Scarabées de cristal à Keyl Swiftclaw, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Regal Drape, 2 Obsidian Idols, 5 Clay Scarabs and 5 Gold Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Drapé royal qiraji, 2 Idoles d'obsidienne, 5 Scarabées d'argile et 5 Scarabées d'or à Keyl Swiftclaw, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Regal Drape, 2 Obsidian Idols, 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Drapé royal qiraji, 2 Idoles d'obsidienne, 5 Scarabées d'or et 5 Scarabées d'argile à Keyl Swiftclaw, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Regal Drape, 2 Vermillion Idols, 5 Silver Scarabs and 5 Bone Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Drapé royal qiraji, 2 Idoles vermillon, 5 Scarabées d'argent et 5 Scarabées d'os à Keyl Vivegriffe, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Spiked Hilt, 2 Amber Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Manche à pointes qiraji, 2 Idoles d'ambre, 5 Scarabées en bronze et 5 Scarabées d'ivoire au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 1 Qiraji Spiked Hilt, 2 Azure Idols, 5 Silver Scarabs and 5 Bone Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest."] = "Apporter 1 Manche à pointes qiraji, 2 Idoles azur, 5 Scarabées d'argent et 5 Scarabées d'os au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.Kill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn."] = "Apporter 10 Ailes de busard grillées et 5 bouteilles de Vin de Junglevine dans le Canot de sauvetage du capitaine Smotts.  Tuer Negolash, et apporter le Coutelas de Smotts au capitaine Smotts, à Strangleronce.",
    ["Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay."] = "Apporter 10 Tas de roseaux akiris au corsaire Bloads à Baie-du-Butin.",
    ["Bring 10 Filled Pure Sample Jars to Laris Geardawdle in Ironforge.If you have trouble finding them, perhaps try to get more clues from Laris."] = "Apporter 10 Pots remplis d'échantillon pur à Laris Geardawdle, à Ironforge.  Si vous éprouvez des difficultés à les trouver, allez voir Laris pour obtenir plus d'indices.",
    ["Bring 10 Highperch Venom Sacs to Fiora Longears in Theramore."] = "Apporter 10 Glandes à venin de Haut-perchoir à Fiora Longears à Theramore.",
    ["Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows."] = "Apporter 10 Pattes de clampants monstrueux à Dar dans le marais des Chagrins.",
    ["Bring 10 Morrowgrain to Quintis Jonespyre in Feathermoon Stronghold."] = "Apporter 10 Fibres d'aurore à Quintis Jonespyre au bastion de Feathermoon.",
    ["Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas."] = "Fournir 10 Peaux de yéti Griffe Féroce à Pratt McGrubben au bastion de Feathermoon, en Feralas.",
    ["Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill."] = "Apporter 10 Anneaux de la Croisade écarlate au Garde noir Burgess à Brill.",
    ["Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay."] = "Apporter 10 Cristaux bleus chantants à Crank Fizzlebub, à Baie-du-Butin.",
    ["Bring 10 Thick Yeti Hides to Jangdor Swiftstrider in Camp Mojache."] = "Apporter 10 Peaux de yéti épaisses à Jangdor Swiftstrider au Camp Mojache.",
    ["Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus."] = "Apporter 10 Pendentifs du Crépuscule au Garde d'argent Manados à Darnassus.",
    ["Bring 10 Webwood Venom Sacs to Gilshalan Windwalker at Aldrassil."] = "Apporter 10 Glandes à venin Tissebois à Gilshalan Windwalker, à Aldrassil.",
    ["Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill."] = "Apporter 10 Fioles de sang de lion des montagnes à l'Apothicaire Lydon à Moulin-de-Tarren.",
    ["Bring 12 Red Burlap Bandanas to Deputy Willem outside the Northshire Abbey."] = "Apporter 12 Masques rouges à l'Adjoint Willem à l'extérieur de l'Abbaye de Northshire.",
    ["Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads."] = "Apporter 12 Œufs de silithide et la Griffe d'excavation à Korran, à la Croisée.",
    ["Bring 12 Timberling Sprouts to Denalan at Lake Al'Ameth."] = "Apporter 12 Pousses de sylvain à Denalan au lac Al'Ameth.",
    ["Bring 12 Tunnel Rat Ears to Mountaineer Kadrell in Thelsamar."] = "Apporter 12 Oreilles de Rat des tunnels au Montagnard Kadrell à Thelsamar.",
    ["Bring 12 pieces of Light Leather to Veren Tallstrider in Thunder Bluff."] = "Apporter 12 pièces de Cuir léger à Veren Tallstrider, à Thunder Bluff.",
    ["Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay."] = "Apporter 12 Echantillons de Mixture de Zanzil à Crank Fizzlebub à Baie-du-Butin.",
    ["Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 17 Cenarion Tactical Badges and 1 Mark of Remulos to Vargus at Cenarion Hold in Silithus. You must also attain Revered reputation with Cenarion Circle to be able to complete this quest."] = "Ramener 15 Badges cénariens de combat, 20 Badges cénariens de logistique, 17 Badges cénariens de tactique et 1 Marque de Remulos à Vargus, au Fort cénarien en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 20 Cenarion Tactical Badges and 1 Mark of Cenarius to Vargus at Cenarion Hold in Silithus. You must also attain Exalted reputation with Cenarion Circle to be able to complete this quest."] = "Ramener 15 Badges cénariens de combat, 20 Badges cénariens de logistique, 20 Badges cénariens de tactique et 1 Marque de Cénarius à Vargus, au Fort cénarien en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 15 Centaur Bracers to Regthar Deathgate, west of the Crossroads."] = "Apporter 15 Bracelets de centaures à Regthar Deathgate, à l'ouest de la Croisée.",
    ["Bring 15 Centaur Ears to Corporal Melkins at Nijel's Point in Desolace."] = "Apporter 15 Oreilles de centaures au caporal Melkins, à la combe de Nijel, en Désolace.",
    ["Bring 15 Red Leather Bandanas to Scout Galiaan at Sentinel Hill."] = "Apporter 15 Masques en cuir rouge à l'éclaireur Galiaan à la Colline des sentinelles.",
    ["Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp."] = "Apporter 20 Têtes réduites à Nimboya au campement Grom'gol.",
    ["Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp."] = "Apporter 25 Colliers d'os brisés à Kin'weelay au Campement Grom'gol.",
    ["Bring 30 Runecloth to Meilosh in Timbermaw Hold."] = "Apportez 30 pièces d'étoffe runique à Meilosh au Repaire des Grumegueules.",
    ["Bring 5 Cenarion Combat Badges, 3 Cenarion Logistics Badges and 7 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus. You must also attain Friendly reputation with Cenarion Circle to be able to complete this quest."] = "Apportez 5 Badges cénariens de combat, 3 Badges cénariens de logistique et 7 Badges cénariens de tactique à Vargus, au Fort cénarien en Silithus. Pour terminer cette quête, il faut aussi que le Cercle cénarien soit au moins Amical à votre égard.",
    ["Bring 5 Charged Thunder Lizard Organs to Rezlak near Drygulch Ravine."] = "Apportez 5 organes de lézard-tonnerre chargés à Rezlak, près du ravin Asséché.",
    ["Bring 5 Iron Pikes and 5 Iron Rivets to Foreman Oslow in Lakeshire."] = "Apporter 5 Clous en fer et 5 Vis en fer au contremaître Oslow à Lakeshire.",
    ["Bring 5 Mossy Tumors to Rellian Greenspyre in Darnassus."] = "Apporter 5 Tumeurs moussues à Rellian Greenspyre à Darnassus.",
    ["Bring 5 Scaber Stalks and 1 Death Cap to Barithras Moonshade in Auberdine."] = "Apporter 5 Pédoncules d'Amanite et 1 Amanite phalloïde à Barithras Moonshade à Auberdine.",
    ["Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo."] = "Apporter 5 Antennes mobiles à Ruga Ragetotem au Camp Taurajo.",
    ["Bring 6 Mathystra Relics to Onu at the Grove of the Ancients."] = "Apporter 6 Reliques de Mathystra à Onu, au Bosquet des Anciens.",
    ["Bring 6 Red Linen Bandanas to Sara Timberlain at the Eastvale Logging Camp."] = "Apporter 6 Masques rouge en lin à Sara Timberlain au Camp de bûcherons du Val d'est.",
    ["Bring 6 Shimmerweeds to Rejold Barleybrew in the Brewnall Village."] = "Apporter 6 Brins de chatoyante à Rejold Barleybrew au village de Brassetout.",
    ["Bring 6 Worgen Bits to Dalar Dawnweaver in The Sepulcher."] = "Rapportez 6 morceaux worgens à Dalar Tisselaube au Sépulcre.",
    ["Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity."] = "Apporter 6 Echantillons de Mousse de Rampant du lac, 6 échantillons de Mousse de Furtif du lac et une Tumeur durcie au Maître Apothicaire Faranell à Undercity.",
    ["Bring 60 Bristleback Quilboar Tusks to Mankrik at the Crossroads."] = "Apporter 60 Défenses de huran Dos-hirsute à Mankrik, à la Croisée.",
    ["Bring 7 Cenarion Combat Badges, 4 Cenarion Logistics Badges and 4 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus. You must also attain Honored reputation with Cenarion Circle to be able to complete this quest."] = "Ramener 7 Badges cénariens de combat, 4 Badges cénariens de logistique et 4 Badges cénariens de tactique à Vargus, au Fort cénarien en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête.",
    ["Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp."] = "Apporter 7 Remèdes tropicaux et 1 Extrait de fougère vénéneuse au sergentYohwa au Camp rebelle.",
    ["Bring 8 Crystalized Scales to Collin Mauren in Stormwind."] = "Apporter 8 Ecailles de cristal à Collin Mauren à Stormwind.",
    ["Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands."] = "Apporter 8 Pierres de puissance Dentrium et 8 Pierres de puissance An'Alleum à Rigglefuzz dans les Terres ingrates.",
    ["Bring 8 Dinosaur Bones to Spark Nilminer in Un'Goro Crater."] = "Apporter 8 Os de dinosaure à Spark Nilminer, au cratère d'Un'Goro.",
    ["Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace."] = "Apporter 8 Fantôm-o-plasmes et la Caisse d'aimants fantômes à Hornizz Brimbuzzle, en Désolace.",
    ["Bring 8 Gnoll Paws to Captain Danuvin on Sentinel Hill."] = "Rapportez 8 Pattes de gnolls au capitaine Danuvin à la Colline des sentinelles.",
    ["Bring 8 Murloc Fins to Dockmaster Baren in Lakeshire."] = "Apporter 8 Ailerons de murloc au Chef des docks Baren à Lakeshire",
    ["Bring 8 Painted Gnoll Armbands to Deputy Rainer at the Barracks."] = "Apporter 8 Brassards peints de gnolls à l'Adjoint Rainer à la Caserne.",
    ["Bring 8 Root Samples to Mebok Mizzyrix in Ratchet."] = "Apporter 8 Echantillons de Racines à Mebok Mizzyrix, à Ratchet.",
    ["Bring 8 Torn Murloc Fins to Guard Thomas at the east Elwynn bridge."] = "Ramener 8 Ailerons de murloc au garde Thomas au Pont est d'Elwynn.",
    ["Bring 8 pieces of Tough Wolf Meat to Eagan Peltskinner outside Northshire Abbey."] = "Apporter 8 pièces de Viande de loup coriace à Eagan Peltskinner, à l'extérieur de l'Abbaye de Northshire.",
    ["Bring 9 Blue Pearls to Rigglefuzz in the Badlands."] = "Apporter 9 Perles bleues à Rigglefuzz dans les Terres ingrates.",
    ["Bring Al'tabim the All-Seeing Primal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.Al'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale."] = "Ramenez des Manchettes primordiales hakkari à Al'tabim Qui-voit-tout. La tribu Zandalar doit aussi être Amicale (au minimum).  Al'tabim Qui-voit-tout se trouve sur l'île de Yojamba, dans la vallée de Strangleronce.",
    ["Bring Al'tabim the All-Seeing a Primal Hakkari Kossack. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.Al'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale."] = "Ramenez une Casaque primordiale hakkari à Al'tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Révérer (au minimum).  Al'tabim Qui-voit-tout se trouve sur l'île de Yojamba, dans la vallée de Strangleronce.",
    ["Bring Al'tabim the All-Seeing a Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.Al'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale."] = "Ramenez un Châle primordial hakkari à Al'tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Honorer (au minimum).  Al'tabim Qui-voit-tout se trouve sur l'île de Yojamba, dans la vallée de Strangleronce.",
    ["Bring Archbishop Benedictus the Cursed Eye of Paleth. Benedictus is in the Cathedral of Light, in the city of Stormwind."] = "Apporter l'Oeil maudit de Paleth à l'archevêque Benedictus, à la cathédrale de la Lumière de la ville de Stormwind.",
    ["Bring Bartolo Ginsetti of Southshore a Bolt of Wool, a Hillman's Cloak, Fine Thread and 10 clumps of Yeti Fur."] = "Apporter à Bartolo Ginsetti de Southshore une Pelote de laine, une Cape d'homme des collines, du Fil fin et 10 Touffes de fourrure de yéti.",
    ["Bring Bernice's Necklace to \"Auntie\" Bernice Stonefield at the Stonefield Farm."] = "Rapporter le Collier de Bernice à \"Tatie\" Bernice Stonefield à la ferme des Stonefield.",
    ["Bring Calor's note to Jonathan Carevin."] = "Apporter la lettre de Calor à Jonathan Carevin.",
    ["Bring Deathclasp's Pincer to Vish Kozus, Captain of the Guard."] = "Apporter la Pince de Poigne-de-mort à Vish Kozus, capitaine de la garde.",
    ["Bring Eggs of the Bloodtalon Matriarch to Xar'Ti in Sen'jin Village."] = "Apportez les œufs de la matriarche griffesang à Xar'Ti, au village de Sen'jin.",
    ["Bring Executor Arren 12 Scarlet Armbands from Scarlet Converts and Scarlet Initiates."] = "Apporter à l'Exécuteur Arren 12 Bracelets écarlates, que vous trouverez sur des Convertis écarlates et des Initiés écarlates.",
